import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
import db from "../db.server";

// ---------------------------------------------------------------------------
// CORS
// ---------------------------------------------------------------------------

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;

const VALID_EVENT_TYPES = [
  "view",
  "click",
  "recommend",
  "convert",
  "dismiss",
] as const;

type EventType = (typeof VALID_EVENT_TYPES)[number];

interface AnalyticsEventBody {
  shop: string;
  eventType: EventType;
  sizeChartId?: string;
  productId?: string;
  metadata?: Record<string, unknown>;
}

// ---------------------------------------------------------------------------
// Preflight
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }
  return Response.json(
    { error: "Method not allowed" },
    { status: 405, headers: CORS_HEADERS },
  );
};

// ---------------------------------------------------------------------------
// Action — POST /api/analytics-event
// Body JSON: { shop, eventType, sizeChartId?, productId?, metadata? }
// ---------------------------------------------------------------------------

export const action = async ({ request }: ActionFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  if (request.method !== "POST") {
    return Response.json(
      { error: "Method not allowed" },
      { status: 405, headers: CORS_HEADERS },
    );
  }

  let body: Partial<AnalyticsEventBody>;

  try {
    body = (await request.json()) as Partial<AnalyticsEventBody>;
  } catch {
    return Response.json(
      { error: "Invalid JSON body" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  const { shop, eventType, sizeChartId, productId, metadata } = body;

  // Validate shop
  if (!shop || !SHOP_RE.test(shop)) {
    return Response.json(
      { error: "Invalid or missing shop parameter" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  // Validate eventType
  if (
    !eventType ||
    !(VALID_EVENT_TYPES as readonly string[]).includes(eventType)
  ) {
    return Response.json(
      {
        error: `eventType must be one of: ${VALID_EVENT_TYPES.join(", ")}`,
      },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  // Fire-and-forget: respond immediately and write in the background
  // We still await to keep error handling consistent, but we return fast
  // because DB writes are non-blocking in practice at this scale
  try {
    const metadataJson =
      metadata !== undefined && metadata !== null
        ? JSON.stringify(metadata)
        : "{}";

    await db.analyticsEvent.create({
      data: {
        shop,
        eventType,
        sizeChartId: sizeChartId ?? null,
        productId: productId ?? null,
        metadata: metadataJson,
      },
    });

    return Response.json({ ok: true }, { headers: CORS_HEADERS });
  } catch (error) {
    // Non-critical: tracking failures should not break the storefront
    // Still return 200 to avoid retries from the widget
    return Response.json({ ok: true }, { headers: CORS_HEADERS });
  }
};

import type { LoaderFunctionArgs } from "react-router";
import db from "../db.server";

// ---------------------------------------------------------------------------
// CORS
// ---------------------------------------------------------------------------

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type",
};

// ---------------------------------------------------------------------------
// Cache
// ---------------------------------------------------------------------------

const CACHE_MAX_AGE = 300; // 5 minutes

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

const SHOP_RE = /^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/;

// ---------------------------------------------------------------------------
// Default widget config
// Mirrors WidgetConfig Prisma model defaults exactly
// ---------------------------------------------------------------------------

const WIDGET_CONFIG_DEFAULTS = {
  displayMode: "popup",
  position: "bottom-right",
  triggerType: "button",
  primaryColor: "#000000",
  successColor: "#16a34a",
  errorColor: "#dc2626",
  backgroundColor: "#ffffff",
  textColor: "#111111",
  borderRadius: "8",
  heading: "Size Guide",
  placeholder: "Select your size",
  buttonText: "Find My Size",
  successMessage: "This size should fit you well!",
  errorMessage:
    "We couldn't determine your size. Please refer to the chart.",
  showRecommender: true,
  customCss: "",
} as const;

// ---------------------------------------------------------------------------
// Loader — GET /api/widget-config
// Query params: shop (required)
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  const url = new URL(request.url);
  const shop = url.searchParams.get("shop");

  if (!shop || !SHOP_RE.test(shop)) {
    return Response.json(
      { error: "Invalid or missing shop parameter" },
      { status: 400, headers: CORS_HEADERS },
    );
  }

  try {
    const config = await db.widgetConfig.findUnique({ where: { shop } });

    const responseHeaders = {
      ...CORS_HEADERS,
      "Cache-Control": `public, max-age=${CACHE_MAX_AGE}`,
    };

    if (!config) {
      // Return defaults when no config has been saved yet
      return Response.json(
        { config: WIDGET_CONFIG_DEFAULTS },
        { headers: responseHeaders },
      );
    }

    return Response.json(
      {
        config: {
          displayMode: config.displayMode,
          position: config.position,
          triggerType: config.triggerType,
          primaryColor: config.primaryColor,
          successColor: config.successColor,
          errorColor: config.errorColor,
          backgroundColor: config.backgroundColor,
          textColor: config.textColor,
          borderRadius: config.borderRadius,
          heading: config.heading,
          placeholder: config.placeholder,
          buttonText: config.buttonText,
          successMessage: config.successMessage,
          errorMessage: config.errorMessage,
          showRecommender: config.showRecommender,
          customCss: config.customCss,
        },
      },
      { headers: responseHeaders },
    );
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Internal server error";
    return Response.json(
      { error: message },
      { status: 500, headers: CORS_HEADERS },
    );
  }
};

