 22→  Icon,
 23→  Modal,
 24→  InlineGrid,
 25→} from "@shopify/polaris";
 26→import { CheckCircleIcon, XCircleIcon, StarIcon } from "@shopify/polaris-icons";
 27→
 28→// ─── Plan display data ──────────────────────────────────────────────────────
 29→
 30→const PLAN_ORDER = ["free", "starter", "growth", "pro"] as const;
 31→
 32→const PLAN_DESCRIPTIONS: Record<string, string> = {
 33→  free: "Get started — no credit card required",
 34→  starter: "Essential tools for growing stores",
 35→  growth: "AI-powered sizing for serious brands",
 36→  pro: "Enterprise-grade power and control",
 37→};
 38→
 39→// ─── Feature rows for comparison table ──────────────────────────────────────
 40→
 41→const FEATURE_ROWS: { label: string; key: keyof Plan["limits"] }[] = [
 42→  { label: "Published size charts", key: "maxCharts" },
 43→  { label: "CSV import / export", key: "csvImport" },
 44→  { label: "Auto-assignment rules", key: "autoAssign" },
 45→  { label: "Image support in charts", key: "imageInCharts" },
 46→  { label: "Translate & Adapt (i18n)", key: "translateAdapt" },
 47→  { label: "Analytics dashboard", key: "analytics" },
 48→  { label: "Dedicated sizing page", key: "dedicatedSizingPage" },
 49→  { label: "AI size recommender", key: "aiRecommender" },
 50→  { label: "Advanced ML recommender", key: "advancedAi" },
 51→  { label: "Return attribution", key: "returnAttribution" },
 52→  { label: "Priority support (<2hr)", key: "prioritySupport" },
 53→  { label: "Multi-store sync", key: "multiStore" },
 54→];
 55→
 56→// ─── Loader ─────────────────────────────────────────────────────────────────
 57→
 58→export const loader = async ({ request }: LoaderFunctionArgs) => {
 59→  const { session } = await authenticate.admin(request);
 60→  const subscription = await db.subscription.findUnique({
 61→    where: { shop: session.shop },
 62→  });
 63→  return {
 64→    currentPlan: getPlan(subscription?.planId ?? "free"),
 65→    billingInterval: subscription?.billingInterval ?? "monthly",
 66→    plans: PLANS,
 67→  };
 68→};
 69→
 70→// ─── Action ─────────────────────────────────────────────────────────────────
 71→
 72→export const action = async ({ request }: ActionFunctionArgs) => {
 73→  const { session } = await authenticate.admin(request);
 74→  const shop = session.shop;
 75→  const formData = await request.formData();
 76→  const intent = formData.get("intent") as string;
 77→
 78→  try {
 79→    if (intent === "subscribe") {
 80→      const planId = formData.get("planId") as string;
 81→      const interval = (formData.get("interval") as string) || "monthly";
 82→      const plan = getPlan(planId);
 83→
 84→      if (plan.price === 0) {
 85→        await db.subscription.upsert({
 86→          where: { shop },
 87→          update: { planId: "free", status: "active", billingInterval: "monthly" },
 88→          create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
 89→        });
 90→        return { ok: true, message: "Switched to Free plan" };
 91→      }
 92→
 93→      // Production: call Shopify billing API here
 94→      // For now, simulate by updating local DB
 95→      await db.subscription.upsert({
 96→        where: { shop },
 97→        update: { planId, billingInterval: interval, status: "active" },
 98→        create: { shop, planId, billingInterval: interval, status: "active" },
 99→      });
100→
101→      return { ok: true, message: `Subscribed to ${plan.name} plan` };
102→    }
103→
104→    if (intent === "cancel") {
105→      await db.subscription.upsert({
106→        where: { shop },
107→        update: { planId: "free", status: "active", billingInterval: "monthly" },
108→        create: { shop, planId: "free", billingInterval: "monthly", status: "active" },
109→      });
110→      return { ok: true, message: "Subscription cancelled. You are now on the Free plan." };
111→    }
112→
113→    return { error: "Unknown action" };
114→  } catch (error) {
115→    return { error: error instanceof Error ? error.message : "An unexpected error occurred" };
116→  }
117→};
118→
119→// ─── Feature row ────────────────────────────────────────────────────────────
120→
121→function PlanFeature({ feature }: { feature: string }) {
122→  return (
123→    <InlineStack gap="200" blockAlign="start" wrap={false}>
124→      <Box>
125→        <Icon source={CheckCircleIcon} tone="success" />
126→      </Box>
127→      <Text as="span" variant="bodyMd">
128→        {feature}
129→      </Text>
130→    </InlineStack>
131→  );
132→}
133→
134→// ─── Plan card ──────────────────────────────────────────────────────────────
135→
136→interface PlanCardProps {
137→  plan: Plan;
138→  isAnnual: boolean;
139→  currentTier: string;
140→  onSubscribe: (planId: string) => void;
141→  onRequestCancel: () => void;
142→  isLoading: boolean;
143→}
144→
145→function PlanCard({
146→  plan,
147→  isAnnual,
148→  currentTier,
149→  onSubscribe,
150→  onRequestCancel,
151→  isLoading,
152→}: PlanCardProps) {
153→  const isCurrent = currentTier === plan.id;
154→  const isMostPopular = plan.id === "growth";
155→  const tierIndex = PLAN_ORDER.indexOf(plan.id as (typeof PLAN_ORDER)[number]);
156→  const currentIndex = PLAN_ORDER.indexOf(currentTier as (typeof PLAN_ORDER)[number]);
157→  const isUpgrade = tierIndex > currentIndex;
158→  const isDowngrade = tierIndex < currentIndex;
159→
160→  const displayPrice = isAnnual
161→    ? (plan.annualPrice / 12).toFixed(2)
162→    : plan.price.toFixed(2);
163→
164→  let buttonContent = "Start free trial";
165→  let buttonVariant: "primary" | "secondary" | undefined = "primary";
166→  let buttonTone: "critical" | undefined = undefined;
167→
168→  if (isCurrent) {
169→    buttonContent = "Current plan";
170→    buttonVariant = "secondary";
171→  } else if (plan.price === 0) {
172→    buttonContent = "Downgrade to Free";
173→    buttonVariant = undefined;
174→    buttonTone = "critical";
175→  } else if (isUpgrade) {
176→    buttonContent = `Upgrade to ${plan.name}`;
177→  } else if (isDowngrade) {
178→    buttonContent = `Switch to ${plan.name}`;
179→  }
180→
181→  const handleClick = () => {
182→    if (isCurrent) return;
183→    if (plan.price === 0) {
184→      onRequestCancel();
185→    } else {
186→      onSubscribe(plan.id);
187→    }
188→  };
189→
190→  return (
191→    <Card>
192→      <BlockStack gap="400">
193→        {/* Plan name + badges */}
194→        <BlockStack gap="100">
195→          <InlineStack align="space-between" blockAlign="center">
196→            <Text as="h3" variant="headingMd" fontWeight="bold">
197→              {plan.name}
198→            </Text>
199→            <InlineStack gap="150">
200→              {isMostPopular && !isCurrent && (
201→                <Badge tone="info" icon={StarIcon}>
202→                  Most popular
203→                </Badge>
204→              )}
205→              {isCurrent && <Badge tone="success">Active</Badge>}
206→            </InlineStack>
207→          </InlineStack>
208→          <Text as="p" variant="bodySm" tone="subdued">
209→            {PLAN_DESCRIPTIONS[plan.id] ?? ""}
210→          </Text>
211→        </BlockStack>
212→
213→        <Divider />
214→
215→        {/* Price */}
216→        <BlockStack gap="100">
217→          {plan.price === 0 ? (
218→            <>
219→              <Text as="p" variant="headingXl" fontWeight="bold">
220→                Free
221→              </Text>
222→              <Text as="p" variant="bodySm" tone="subdued">
223→                forever — no credit card
224→              </Text>
225→            </>
226→          ) : (
227→            <>
228→              <InlineStack gap="100" blockAlign="baseline">
229→                <Text as="p" variant="headingXl" fontWeight="bold">
230→                  ${displayPrice}
231→                </Text>
232→                <Text as="p" variant="bodySm" tone="subdued">
233→                  / month
234→                </Text>
235→              </InlineStack>
236→              <Text as="p" variant="bodySm" tone="subdued">
237→                {isAnnual
238→                  ? `billed $${plan.annualPrice} / year`
239→                  : `or $${(plan.annualPrice / 12).toFixed(2)}/mo billed annually`}
240→              </Text>
241→            </>
242→          )}
243→        </BlockStack>
244→
245→        {/* CTA button */}
246→        <Button
247→          variant={buttonVariant}
248→          tone={buttonTone}
249→          onClick={handleClick}
250→          disabled={isCurrent}
251→          loading={isLoading && !isCurrent}
252→          fullWidth
253→        >
254→          {buttonContent}
255→        </Button>
256→
257→        <Divider />
258→
259→        {/* Features list */}
260→        <BlockStack gap="300">
261→          {plan.features.map((f) => (
262→            <PlanFeature key={f} feature={f} />
263→          ))}
264→        </BlockStack>
265→      </BlockStack>
266→    </Card>
267→  );
268→}
269→
270→// ─── Page ───────────────────────────────────────────────────────────────────
271→
272→export default function PricingPage() {
273→  const { currentPlan, billingInterval: initialInterval, plans } =
274→    useLoaderData<typeof loader>();
275→  const fetcher = useFetcher<typeof action>();
276→  const navigate = useNavigate();
277→  const shopify = useAppBridge();
278→
279→  const [isAnnual, setIsAnnual] = useState(initialInterval === "annual");
280→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
281→
282→  const isFetching = fetcher.state !== "idle";
283→
284→  useEffect(() => {
285→    const data = fetcher.data;
286→    if (data && "ok" in data && data.ok) {
287→      shopify.toast.show(data.message ?? "Plan updated");
288→    } else if (data && "error" in data) {
289→      shopify.toast.show(data.error ?? "Error", { isError: true });
290→    }
291→  }, [fetcher.data, shopify]);
292→
293→  const handleSubscribe = useCallback(
294→    (planId: string) => {
295→      fetcher.submit(
296→        { intent: "subscribe", planId, interval: isAnnual ? "annual" : "monthly" },
297→        { method: "post" },
298→      );
299→    },
300→    [fetcher, isAnnual],
301→  );
302→
303→  const handleConfirmCancel = useCallback(() => {
304→    setCancelModalOpen(false);
305→    fetcher.submit({ intent: "cancel" }, { method: "post" });
306→  }, [fetcher]);
307→
308→  const orderedPlans = PLAN_ORDER.map((id) => plans.find((p) => p.id === id)).filter(
309→    (p): p is Plan => p !== undefined,
310→  );
311→
312→  // Next tier for upgrade banner
313→  const nextTier =
314→    currentPlan.id === "free"
315→      ? "starter"
316→      : currentPlan.id === "starter"
317→        ? "growth"
318→        : currentPlan.id === "growth"
319→          ? "pro"
320→          : null;
321→
322→  const actionError =
323→    fetcher.data && "error" in fetcher.data ? fetcher.data.error : null;
324→
325→  return (
326→    <Page
327→      title="Plans & Pricing"
328→      subtitle="Simple, transparent pricing. No per-order fees ever."
329→      backAction={{ onAction: () => navigate("/app") }}
330→    >
331→      <Box paddingBlockEnd="1600">
332→        <Layout>
333→          {/* Error banner */}
334→          {actionError && (
335→            <Layout.Section>
336→              <Banner tone="critical" title="Billing error">
337→                <Text as="p" variant="bodyMd">
338→                  {actionError}
339→                </Text>
340→              </Banner>
341→            </Layout.Section>
342→          )}
343→
344→          <Layout.Section>
345→            <BlockStack gap="600">
346→              {/* Current plan status */}
347→              {nextTier ? (
348→                <Banner
349→                  tone="info"
350→                  title={`You're on the ${currentPlan.name} plan`}
351→                  action={{
352→                    content: `Upgrade to ${getPlan(nextTier).name}`,
353→                    onAction: () => handleSubscribe(nextTier),
354→                  }}
355→                >
356→                  <Text as="p" variant="bodyMd">
357→                    {currentPlan.id === "free"
358→                      ? "You have up to 3 published charts and basic widget access. Upgrade to unlock more."
359→                      : `Upgrade to ${getPlan(nextTier).name} for more features.`}
360→                  </Text>
361→                </Banner>
362→              ) : (
363→                <Banner tone="success" title={`You're on the ${currentPlan.name} plan`}>
364→                  <InlineStack gap="200" blockAlign="center">
365→                    <Badge tone="success">Active</Badge>
366→                    <Text as="p" variant="bodyMd">
367→                      You have full access to all features including advanced AI and priority support.
368→                    </Text>
369→                  </InlineStack>
370→                </Banner>
371→              )}
372→
373→              {/* Billing toggle */}
374→              <BlockStack gap="200" inlineAlign="center">
375→                <ButtonGroup variant="segmented">
376→                  <Button pressed={!isAnnual} onClick={() => setIsAnnual(false)}>
377→                    Monthly
378→                  </Button>
379→                  <Button pressed={isAnnual} onClick={() => setIsAnnual(true)}>
380→                    Annual · Save 20%
381→                  </Button>
382→                </ButtonGroup>
383→                {isAnnual && (
384→                  <Badge tone="success">You save up to 20% per year</Badge>
385→                )}
386→              </BlockStack>
387→
388→              {/* Plan cards — responsive 4-column grid */}
389→              <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
390→                {orderedPlans.map((plan) => (
391→                  <PlanCard
392→                    key={plan.id}
393→                    plan={plan}
394→                    isAnnual={isAnnual}
395→                    currentTier={currentPlan.id}
396→                    onSubscribe={handleSubscribe}
397→                    onRequestCancel={() => setCancelModalOpen(true)}
398→                    isLoading={isFetching}
399→                  />
400→                ))}
401→              </InlineGrid>
402→
403→              {/* Trial footnote */}
404→              {currentPlan.price === 0 && (
405→                <Text as="p" variant="bodySm" tone="subdued" alignment="center">
406→                  All paid plans include a 7-day free trial. No credit card charged until the trial ends.
407→                </Text>
408→              )}
409→
410→              {/* Guarantee */}
411→              <Banner tone="success" title="30-day money-back guarantee">
412→                <Text as="p" variant="bodyMd">
413→                  Not happy in the first 30 days? We'll refund you — no questions asked.
414→                  Cancel anytime directly from Shopify billing settings.
415→                </Text>
416→              </Banner>
417→
418→              {/* Why switch */}
419→              <BlockStack gap="400">
420→                <Text as="h2" variant="headingLg">
421→                  Why merchants switch to us
422→                </Text>
423→                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
424→                  <Card>
425→                    <BlockStack gap="200">
426→                      <Text as="h3" variant="headingMd" fontWeight="bold">
427→                        No Per-Order Fees
428→                      </Text>
429→                      <Text as="p" variant="bodyMd" tone="subdued">
430→                        Competitors charge per order — costs balloon as your store grows.
431→                        We use simple flat monthly pricing. Your bill stays predictable.
432→                      </Text>
433→                    </BlockStack>
434→                  </Card>
435→                  <Card>
436→                    <BlockStack gap="200">
437→                      <Text as="h3" variant="headingMd" fontWeight="bold">
438→                        Mobile-First Widget
439→                      </Text>
440→                      <Text as="p" variant="bodyMd" tone="subdued">
441→                        iOS Safari bugs are the #1 complaint in competitor reviews.
442→                        Our widget is pixel-perfect on every device.
443→                      </Text>
444→                    </BlockStack>
445→                  </Card>
446→                  <Card>
447→                    <BlockStack gap="200">
448→                      <Text as="h3" variant="headingMd" fontWeight="bold">
449→                        Set Up in 5 Minutes
450→                      </Text>
451→                      <Text as="p" variant="bodyMd" tone="subdued">
452→                        Auto-detect product types, suggest templates, and auto-assign charts.
453→                        Most merchants publish their first chart in under 3 minutes.
454→                      </Text>
455→                    </BlockStack>
456→                  </Card>
457→                </InlineGrid>
458→              </BlockStack>
459→
460→              {/* Full Feature Comparison */}
461→              <BlockStack gap="400">
462→                <Text as="h2" variant="headingLg">
463→                  Full Feature Comparison
464→                </Text>
465→                <Card>
466→                  <BlockStack gap="0">
467→                    {/* Header row */}
468→                    <Box paddingBlockEnd="300">
469→                      <InlineStack align="space-between">
470→                        <Box minWidth="200px">
471→                          <Text as="p" variant="bodySm" tone="subdued">
472→                            Feature
473→                          </Text>
474→                        </Box>
475→                        {orderedPlans.map((plan) => (
476→                          <Box key={plan.id} minWidth="100px">
477→                            <BlockStack gap="100" inlineAlign="center">
478→                              <Text as="p" variant="headingSm" fontWeight="bold">
479→                                {plan.name}
480→                              </Text>
481→                              <Text as="p" variant="bodySm" tone="subdued">
482→                                {plan.price === 0
483→                                  ? "Free"
484→                                  : isAnnual
485→                                    ? `$${(plan.annualPrice / 12).toFixed(2)}/mo`
486→                                    : `$${plan.price}/mo`}
487→                              </Text>
488→                            </BlockStack>
489→                          </Box>
490→                        ))}
491→                      </InlineStack>
492→                    </Box>
493→
494→                    <Divider />
495→
496→                    {/* Feature rows */}
497→                    {FEATURE_ROWS.map((row) => (
498→                      <Box key={row.key} paddingBlock="300">
499→                        <InlineStack align="space-between" blockAlign="center">
500→                          <Box minWidth="200px">
501→                            <Text as="p" variant="bodyMd">
502→                              {row.label}
503→                            </Text>
504→                          </Box>
505→                          {orderedPlans.map((plan) => {
506→                            const val = plan.limits[row.key];
507→                            if (row.key === "maxCharts") {
508→                              return (
509→                                <Box key={plan.id} minWidth="100px">
510→                                  <InlineStack align="center">
511→                                    <Text as="p" variant="bodyMd" fontWeight="semibold">
512→                                      {val === -1 ? "Unlimited" : String(val)}
513→                                    </Text>
514→                                  </InlineStack>
515→                                </Box>
516→                              );
517→                            }
518→                            return (
519→                              <Box key={plan.id} minWidth="100px">
520→                                <InlineStack align="center">
521→                                  <Icon
522→                                    source={val ? CheckCircleIcon : XCircleIcon}
523→                                    tone={val ? "success" : "subdued"}
524→                                  />
525→                                </InlineStack>
526→                              </Box>
527→                            );
528→                          })}
529→                        </InlineStack>
530→                      </Box>
531→                    ))}
532→                  </BlockStack>
533→                </Card>
534→              </BlockStack>
535→
536→              {/* FAQ */}
537→              <BlockStack gap="400">
538→                <Text as="h2" variant="headingLg">
539→                  Frequently Asked Questions
540→                </Text>
541→                <Card>
542→                  <BlockStack gap="400">
543→                    {[
544→                      {
545→                        q: "Can I switch plans anytime?",
546→                        a: "Yes. Upgrade instantly — new features activate immediately. Downgrades take effect at end of billing period.",
547→                      },
548→                      {
549→                        q: "What happens to my charts if I downgrade?",
550→                        a: "Charts are never deleted. On Free, only 3 most recent stay published. Re-publish anytime you upgrade.",
551→                      },
552→                      {
553→                        q: "Is there a free trial?",
554→                        a: "All paid plans include a 7-day free trial. The Free plan is permanent — not a trial.",
555→                      },
556→                      {
557→                        q: "Are there per-order fees?",
558→                        a: "Never. Flat monthly or annual pricing. No hidden charges, no matter how large your store grows.",
559→                      },
560→                      {
561→                        q: "Does the annual plan auto-renew?",
562→                        a: "Yes. Cancel anytime from Shopify Admin → Settings → Billing. No cancellation fees.",
563→                      },
564→                    ].map((faq, i) => (
565→                      <BlockStack key={i} gap="100">
566→                        <Text as="p" variant="bodyMd" fontWeight="bold">
567→                          {faq.q}
568→                        </Text>
569→                        <Text as="p" variant="bodyMd" tone="subdued">
570→                          {faq.a}
571→                        </Text>
572→                        {i < 4 && <Divider />}
573→                      </BlockStack>
574→                    ))}
575→                  </BlockStack>
576→                </Card>
577→              </BlockStack>
578→            </BlockStack>
579→          </Layout.Section>
580→        </Layout>
581→      </Box>
582→
583→      {/* Downgrade confirmation modal */}
584→      <Modal
585→        open={cancelModalOpen}
586→        onClose={() => setCancelModalOpen(false)}
587→        title="Downgrade to Free plan?"
588→        primaryAction={{
589→          content: "Yes, downgrade",
590→          destructive: true,
591→          onAction: handleConfirmCancel,
592→          loading: isFetching,
593→        }}
594→        secondaryActions={[
595→          {
596→            content: "Keep current plan",
597→            onAction: () => setCancelModalOpen(false),
598→          },
599→        ]}
600→      >
601→        <Modal.Section>
602→          <BlockStack gap="400">
603→            <Text as="p" variant="bodyMd">
604→              Downgrading to Free will immediately remove access to:
605→            </Text>
606→            <BlockStack gap="200">
607→              {[
608→                "Unlimited size charts — limited to 3",
609→                "CSV import / export",
610→                "Auto-assignment rules",
611→                "Analytics dashboard",
612→                "AI size recommender",
613→                "Priority support",
614→                "Return attribution",
615→              ].map((item) => (
616→                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
617→                  <Text as="span" variant="bodyMd" tone="subdued">
618→                    ·
619→                  </Text>
620→                  <Text as="p" variant="bodyMd">
621→                    {item}
622→                  </Text>
623→                </InlineStack>
624→              ))}
625→            </BlockStack>
626→            <Banner tone="warning">
627→              <Text as="p" variant="bodyMd">
