export default function Settings() {
  const {
    shop,
    chartCount,
    assignmentCount,
    hasWidgetConfig,
    widgetDisplayMode,
    hasRecommenderConfig,
    recommenderEnabled,
    plan,
    isPriority,
    isFreePlan,
  } = useLoaderData<typeof loader>();

  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();
  const isLoading = fetcher.state !== "idle";

  // General settings (client-only — persisted in localStorage for now)
  const [unitSystem, setUnitSystem] = useState<string>("cm");
  const [defaultCategory, setDefaultCategory] = useState<string>("general");
  const [autoPublish, setAutoPublish] = useState<boolean>(false);

  // Import text area
  const [importJson, setImportJson] = useState<string>("");

  // Danger zone confirm text
  const [deleteConfirm, setDeleteConfirm] = useState<string>("");

  // Export download trigger
  const [exportedJson, setExportedJson] = useState<string | null>(null);

  useEffect(() => {
    if (!fetcher.data) return;

    if ("ok" in fetcher.data) {
      shopify.toast.show(fetcher.data.message ?? "Done");

      if (fetcher.data.intent === "export-data" && "exportData" in fetcher.data) {
        setExportedJson(fetcher.data.exportData as string);
      }

      if (fetcher.data.intent === "import-data") {
        setImportJson("");
      }

      if (fetcher.data.intent === "delete-all-charts") {
        setDeleteConfirm("");
      }
    } else if ("error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "An error occurred", { isError: true });
    }
  }, [fetcher.data, shopify]);

  // Trigger browser download when export data is ready
  useEffect(() => {
    if (!exportedJson) return;
    const blob = new Blob([exportedJson], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `size-charts-${shop}-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
    setExportedJson(null);
  }, [exportedJson, shop]);

  const submitIntent = (intent: string, extra?: Record<string, string>) => {
    const fd = new FormData();
    fd.set("intent", intent);
    if (extra) {
      for (const [k, v] of Object.entries(extra)) fd.set(k, v);
    }
    fetcher.submit(fd, { method: "post" });
  };

  const CATEGORIES = [
    "general",
    "tops",
    "bottoms",
    "dresses",
    "shoes",
    "kids",
    "rings",
    "sportswear",
    "outerwear",
  ];

  const unitOptions = [
    { label: "Centimeters (cm)", value: "cm" },
    { label: "Inches (in)", value: "in" },
  ];

  const categoryOptions = CATEGORIES.map((cat) => ({
    label: cat.charAt(0).toUpperCase() + cat.slice(1),
    value: cat,
  }));

  return (
    <Page
      title="Settings"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={
        <Button variant="primary" url="/app/pricing">
          {isFreePlan ? "Upgrade plan" : "Manage billing"}
        </Button>
      }
    >
      <BlockStack gap="600">

        {/* ================================================================ */}
        {/* SECTION 1 — Account Overview                                      */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Account Overview</Text>

            <BlockStack gap="200">
              <InlineStack gap="200" blockAlign="center">
                <Text as="p" variant="bodyMd">Store</Text>
                <Text as="p" variant="bodyMd" tone="subdued">{shop}</Text>
              </InlineStack>
              <Divider />
              <InlineStack gap="200" blockAlign="center">
                <Text as="p" variant="bodyMd">Current plan</Text>
                <Badge tone={isFreePlan ? "enabled" : "success"}>{plan.name}</Badge>
                <Text as="p" variant="bodyMd" tone="subdued">
                  {plan.price === 0 ? "Free forever" : `$${plan.price}/mo`}
                </Text>
              </InlineStack>
              {isFreePlan && (
                <Banner tone="info" title="Upgrade for more features">
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Get unlimited charts, auto-assignment, CSV import/export, AI recommender, and analytics.
                    </Text>
                    <Button variant="primary" url="/app/pricing">View upgrade options</Button>
                  </BlockStack>
                </Banner>
              )}
            </BlockStack>

            <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
              <StatCard
                label="Size charts"
                value={chartCount}
                sub={`${plan.limits.maxCharts === -1 ? "Unlimited" : `${chartCount} of ${plan.limits.maxCharts}`} charts`}
              />
              <StatCard
                label="Assignments"
                value={assignmentCount}
                sub="Products, collections, tags"
              />
            </InlineGrid>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 2 — General Settings                                      */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">General Settings</Text>

            <BlockStack gap="200">
              <Text as="p" variant="bodyMd">Default unit system</Text>
              <Text as="p" variant="bodyMd" tone="subdued">
                Sets the default measurement unit for new size charts. Customers can always switch.
              </Text>
              <Select
                label="Default unit system"
                labelHidden
                options={unitOptions}
                value={unitSystem}
                onChange={(value) => setUnitSystem(value)}
              />
            </BlockStack>

            <Divider />

            <BlockStack gap="200">
              <Text as="p" variant="bodyMd">Default chart category</Text>
              <Text as="p" variant="bodyMd" tone="subdued">
                Pre-selected category when creating a new size chart from scratch.
              </Text>
              <Select
                label="Default chart category"
                labelHidden
                options={categoryOptions}
                value={defaultCategory}
                onChange={(value) => setDefaultCategory(value)}
              />
            </BlockStack>

            <Divider />

            <InlineStack gap="400" blockAlign="center">
              <BlockStack gap="200">
                <Text as="p" variant="bodyMd">Auto-publish new charts</Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  New charts are immediately set to Active instead of Draft.
                </Text>
              </BlockStack>
              <Checkbox
                label="Auto-publish new charts"
                labelHidden
                checked={autoPublish}
                onChange={(checked) => setAutoPublish(checked)}
              />
            </InlineStack>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 3 — Data Management                                       */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Data Management</Text>

            {/* Export */}
            <Card>
              <BlockStack gap="200">
                <Text as="h3" variant="headingMd" fontWeight="bold">Export size charts</Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Download all {chartCount} chart{chartCount === 1 ? "" : "s"} as a JSON file. Includes all assignments and data. Use to back up or migrate to another store.
                </Text>
                <InlineStack gap="200">
                  <Button
                    onClick={() => submitIntent("export-data")}
                    loading={isLoading && fetcher.formData?.get("intent") === "export-data"}
                    disabled={chartCount === 0}
                  >
                    Export all charts
                  </Button>
                </InlineStack>
                {chartCount === 0 && (
                  <Text as="p" variant="bodyMd" tone="subdued">No charts to export.</Text>
                )}
              </BlockStack>
            </Card>

            {/* Import */}
            <Card>
              <BlockStack gap="200">
                <Text as="h3" variant="headingMd" fontWeight="bold">Import charts from JSON</Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  Paste your exported JSON backup below. Existing charts with the same name are skipped.
                </Text>
                {!hasFeature(plan.id, "csvImport") && (
                  <Banner tone="warning" title="Starter plan required">
                    <Text as="p" variant="bodyMd" tone="subdued">
                      Import is available on the Starter plan ($4.99/mo) and above.
                    </Text>
                  </Banner>
                )}
                <TextField
                  label="Import JSON"
                  labelHidden
                  value={importJson}
                  onChange={(value) => setImportJson(value)}
                  placeholder='{"charts": [...]}'
                  multiline={6}
                  autoComplete="off"
                  disabled={!hasFeature(plan.id, "csvImport")}
                />
                <InlineStack gap="200">
                  <Button
                    variant="primary"
                    onClick={() => submitIntent("import-data", { importJson })}
                    loading={isLoading && fetcher.formData?.get("intent") === "import-data"}
                    disabled={!hasFeature(plan.id, "csvImport") || !importJson.trim()}
                  >
                    Import charts
                  </Button>
                </InlineStack>
              </BlockStack>
            </Card>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 4 — Widget Settings Quick Access                          */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Widget Settings</Text>

            <BlockStack gap="200">
              <InlineStack gap="200" blockAlign="center">
                <Text as="p" variant="bodyMd">Widget status</Text>
                <Badge tone={hasWidgetConfig ? "success" : "enabled"}>
                  {hasWidgetConfig ? "Configured" : "Using defaults"}
                </Badge>
              </InlineStack>
              {hasWidgetConfig && widgetDisplayMode && (
                <InlineStack gap="200" blockAlign="center">
                  <Text as="p" variant="bodyMd" tone="subdued">Display mode</Text>
                  <Badge tone="info">{widgetDisplayMode}</Badge>
                </InlineStack>
              )}
              <Text as="p" variant="bodyMd" tone="subdued">
                {hasWidgetConfig
                  ? "Widget is customized with your brand settings."
                  : "Widget is using default appearance settings."}
              </Text>
              <ButtonGroup>
                <Button variant="primary" url="/app/widget">Open Widget Customizer</Button>
                <Button
                  tone="critical"
                  onClick={() => submitIntent("reset-widget")}
                  loading={isLoading && fetcher.formData?.get("intent") === "reset-widget"}
                  disabled={!hasWidgetConfig}
                >
                  Reset to defaults
                </Button>
              </ButtonGroup>
            </BlockStack>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* SECTION 5 — Danger Zone                                           */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">Danger Zone</Text>

            <Banner tone="critical" title="Irreversible actions">
              <Text as="p" variant="bodyMd" tone="subdued">
                These actions cannot be undone. Proceed with caution.
              </Text>
            </Banner>

            <BlockStack gap="400">
              {/* Clear Analytics */}
              <Card>
                <BlockStack gap="200">
                  <Text as="p" variant="bodyMd">Clear analytics data</Text>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Permanently delete all chart view events, recommendation events, and conversion data. This cannot be undone.
                  </Text>
                  <InlineStack gap="200">
                    <Button
                      tone="critical"
                      onClick={() => submitIntent("reset-analytics")}
                      loading={isLoading && fetcher.formData?.get("intent") === "reset-analytics"}
                    >
                      Clear all analytics
                    </Button>
                  </InlineStack>
                </BlockStack>
              </Card>

              {/* Delete All Charts */}
              <Card>
                <BlockStack gap="200">
                  <Text as="p" variant="bodyMd">Delete all size charts</Text>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Permanently delete all {chartCount} size chart{chartCount === 1 ? "" : "s"} and their assignments. Type DELETE below to confirm.
                  </Text>
                  <TextField
                    label='Type "DELETE" to confirm'
                    value={deleteConfirm}
                    onChange={(value) => setDeleteConfirm(value)}
                    placeholder="DELETE"
                    autoComplete="off"
                  />
                  <InlineStack gap="200">
                    <Button
                      tone="critical"
                      onClick={() => submitIntent("delete-all-charts", { confirmText: deleteConfirm })}
                      loading={isLoading && fetcher.formData?.get("intent") === "delete-all-charts"}
                      disabled={deleteConfirm !== "DELETE" || chartCount === 0}
                    >
                      Delete all charts
                    </Button>
                  </InlineStack>
                </BlockStack>
              </Card>
            </BlockStack>
          </BlockStack>
        </Card>

        {/* ================================================================ */}
        {/* APP STATUS + SUPPORT (inline)                                      */}
        {/* ================================================================ */}
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd" fontWeight="bold">App Status</Text>

            <InlineStack gap="400" wrap>
              <StatusRow
                label="Widget config"
                configured={hasWidgetConfig}
                configuredLabel="Configured"
                notConfiguredLabel="Using defaults"
              />
              <StatusRow
                label="AI Recommender"
                configured={recommenderEnabled}
                configuredLabel="Enabled"
                notConfiguredLabel={hasRecommenderConfig ? "Disabled" : "Not set up"}
              />
              <StatusRow
                label="Theme extension"
                configured={chartCount > 0}
                configuredLabel="Charts ready"
                notConfiguredLabel="No charts yet"
              />
              <BlockStack gap="100">
                <Text as="p" variant="bodyMd" tone="subdued">Version</Text>
                <InlineStack gap="200" blockAlign="center">
                  <Text as="p" variant="bodyMd">1.0.0</Text>
                  <Badge tone="success">Built for Shopify</Badge>
                </InlineStack>
              </BlockStack>
              <BlockStack gap="100">
                <Text as="p" variant="bodyMd" tone="subdued">Support</Text>
                <InlineStack gap="200" blockAlign="center">
                  {isPriority ? <Badge tone="success">Priority</Badge> : <Badge tone="new">Standard</Badge>}
                  <Button variant="plain" url="mailto:support@sizechart.app">Email</Button>
                </InlineStack>
              </BlockStack>
            </InlineStack>
          </BlockStack>
        </Card>

      </BlockStack>
    </Page>
  );
}

