        <div
          style={{
            display: "flex",
            gap: "4px",
            background: "#f6f6f7",
            borderRadius: "20px",
            padding: "3px",
            border: "1px solid #e1e3e5",
          }}
        >
          {data.units.available.map((unit) => (
            <button
              key={unit}
              type="button"
              onClick={() => toggleUnit(unit)}
              style={{
                padding: "3px 14px",
                borderRadius: "16px",
                border: "none",
                background:
                  data.units.default === unit ? "#2c6ecb" : "transparent",
                color: data.units.default === unit ? "#ffffff" : "#6d7175",
                fontWeight: data.units.default === unit ? 700 : 500,
                cursor: "pointer",
                fontSize: "12px",
                lineHeight: "20px",
                transition: "all 0.12s ease",
                fontFamily: "inherit",
              }}
            >
              {unit}
            </button>
          ))}
        </div>
        <div
