import type { ActionFunctionArgs } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";

export const action = async ({ request }: ActionFunctionArgs) => {
  const { shop } = await authenticate.webhook(request);

  // Shop/redact: Shopify requests deletion of ALL data for this shop.
  // 48 hours after uninstall — remove everything we stored for this shop.
  await Promise.all([
    db.analyticsEvent.deleteMany({ where: { shop } }),
    db.chartAssignment.deleteMany({ where: { shop } }),
    db.sizeChart.deleteMany({ where: { shop } }),
    db.widgetConfig.deleteMany({ where: { shop } }),
    db.recommenderConfig.deleteMany({ where: { shop } }),
    db.subscription.deleteMany({ where: { shop } }),
    db.session.deleteMany({ where: { shop } }),
  ]);

  return new Response();
};

