  }
  .scr-field-error[hidden] { display: none; }

  /* Submit button */
  .scr-submit-btn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: .6rem;
    width: 100%;
    padding: .75em 1.5em;
    background: var(--scr-primary);
    color: #fff;
    border: none;
    border-radius: var(--scr-radius, 8px);
    font-size: 1rem;
