  .scr-submit-btn:hover { opacity: .87; }
  .scr-submit-btn:active { transform: scale(.98); }
  .scr-submit-btn:disabled { opacity: .6; cursor: not-allowed; }
  .scr-submit-btn:focus-visible {
    outline: 3px solid var(--scr-primary);
