  }
  .scr-submit-spinner {
    width: 18px;
    height: 18px;
    border: 2px solid rgba(255,255,255,.4);
    border-top-color: #fff;
    border-radius: 50%;
    animation: scrSpin .7s linear infinite;
    flex-shrink: 0;
  }
  .scr-submit-spinner[hidden] { display: none; }

  .scr-form-error {
    padding: .6em .9em;
    background: #fef2f2;
    color: var(--scr-error, #dc2626);
    border-radius: calc(var(--scr-radius, 8px) - 2px);
    font-size: .88rem;
    border: 1px solid #fecaca;
  }
  .scr-form-error[hidden] { display: none; }

  /* ── Result ── */
  .scr-result {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: .75rem;
    padding: 1rem 0;
    text-align: center;
