  .scr-unit-hint { font-size: .78rem; font-weight: 400; color: var(--scr-muted, #6b7280); }

  .scr-input,
  .scr-select {
    width: 100%;
    padding: .6em .85em;
    border: 1px solid var(--scr-border, #e5e7eb);
    border-radius: calc(var(--scr-radius, 8px) - 2px);
