  }
  .scr-input:focus,
  .scr-select:focus {
    outline: none;
    border-color: var(--scr-primary);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--scr-primary) 20%, transparent);
  }
  .scr-input[aria-invalid="true"],
  .scr-select[aria-invalid="true"] {
