  .scr-submit-btn:hover { opacity: .87; }
  .scr-submit-btn:active { transform: scale(.98); }
  .scr-submit-btn:disabled { opacity: .6; cursor: not-allowed; }
  .scr-submit-btn:focus-visible {
    outline: 3px solid var(--scr-primary);
    outline-offset: 3px;
  }
  .scr-submit-spinner {
    width: 18px;
    height: 18px;
    border: 2px solid rgba(255,255,255,.4);
    border-top-color: #fff;
    border-radius: 50%;
    animation: scrSpin .7s linear infinite;
    flex-shrink: 0;
  }
  .scr-submit-spinner[hidden] { display: none; }

  .scr-form-error {
    padding: .6em .9em;
    background: #fef2f2;
    color: var(--scr-error, #dc2626);
    border-radius: calc(var(--scr-radius, 8px) - 2px);
    font-size: .88rem;
    border: 1px solid #fecaca;
  }
  .scr-form-error[hidden] { display: none; }

  /* ── Result ── */
  .scr-result {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: .75rem;
    padding: 1rem 0;
    text-align: center;
    animation: scrFadeIn var(--scr-anim) both;
  }
  .scr-result[hidden] { display: none; }
  @keyframes scrFadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }

  .scr-result-badge {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: .25rem;
    background: var(--scr-input-bg, #f9fafb);
    border: 2px solid var(--scr-primary);
    border-radius: calc(var(--scr-radius, 8px) + 4px);
    padding: .75rem 2.5rem;
  }
  .scr-result-label {
    font-size: .78rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: .07em;
    color: var(--scr-muted, #6b7280);
  }
  .scr-result-size {
    font-size: 2.5rem;
    font-weight: 800;
    color: var(--scr-primary);
    line-height: 1;
  }
  .scr-result-message { font-size: .92rem; color: var(--scr-text, #111); margin: 0; max-width: 340px; }

  .scr-result-alts { width: 100%; }
  .scr-result-alts[hidden] { display: none; }
  .scr-alts-label { font-size: .82rem; color: var(--scr-muted, #6b7280); margin: 0 0 .4rem; }
  .scr-alts-list { display: flex; justify-content: center; gap: .5rem; flex-wrap: wrap; }
  .scr-alt-chip {
    display: inline-flex;
    flex-direction: column;
    align-items: center;
    padding: .3em .8em;
    border: 1px solid var(--scr-border, #e5e7eb);
