function AlgorithmCard({
  id,
  label,
  description,
  badge,
  badgeTone,
  selected,
  disabled,
  onSelect,
}: {
  id: string;
  label: string;
  description: string;
  badge: string;
  badgeTone: string;
  selected: boolean;
  disabled: boolean;
  onSelect: (v: string) => void;
}) {
  return (
    <div
      role="button"
      tabIndex={disabled ? -1 : 0}
      onClick={() => !disabled && onSelect(id)}
      onKeyDown={(e) => {
        if (!disabled && (e.key === "Enter" || e.key === " ")) {
          e.preventDefault();
          onSelect(id);
        }
      }}
      style={{
        cursor: disabled ? "not-allowed" : "pointer",
        borderRadius: "12px",
        outline: selected ? "2px solid #005bd3" : "none",
        opacity: disabled ? 0.5 : 1,
        flex: "1 1 0",
        minWidth: "160px",
      }}
    >
      <Card>
        <BlockStack gap="200">
          <InlineStack gap="200" blockAlign="center">
            <Text as="p" variant="bodyMd">{label}</Text>
            {selected && <Badge tone="info">Active</Badge>}
          </InlineStack>
          <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
          <Badge tone={badgeTone as "success" | "enabled" | "warning" | "critical" | "info"}>{badge}</Badge>
        </BlockStack>
      </Card>
    </div>
  );
}

function FitCard({
  id,
  label,
  description,
  selected,
  onSelect,
}: {
  id: string;
  label: string;
  description: string;
  selected: boolean;
  onSelect: (v: string) => void;
}) {
  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => onSelect(id)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          onSelect(id);
        }
      }}
      style={{
        cursor: "pointer",
        borderRadius: "12px",
        outline: selected ? "2px solid #005bd3" : "none",
        flex: "1 1 0",
        minWidth: "120px",
      }}
    >
      <Card>
        <BlockStack gap="200">
          <InlineStack gap="200" blockAlign="center">
            <Text as="p" variant="bodyMd">{label}</Text>
            {selected && <Badge tone="info">Selected</Badge>}
          </InlineStack>
          <Text as="p" variant="bodyMd" tone="subdued">{description}</Text>
        </BlockStack>
      </Card>
    </div>
  );
}

