                      }}
                      placeholder={`Col ${hi + 1}`}
                    />
                    {data.headers.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeColumn(hi)}
                        title="Remove column"
                        style={{
                          background: "none",
                          border: "none",
                          cursor: "pointer",
                          color: "#c9cccf",
                          padding: "2px 4px",
                          borderRadius: "4px",
                          fontSize: "15px",
                          lineHeight: 1,
                          flexShrink: 0,
                          transition: "color 0.1s, background 0.1s",
                          fontFamily: "inherit",
                        }}
                        onMouseEnter={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
