// Table Editor Component
// ---------------------------------------------------------------------------

interface TableEditorProps {
  data: ChartData;
  onChange: (data: ChartData) => void;
}

function TableEditor({ data, onChange }: TableEditorProps) {
  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);

  const updateCell = (rowIndex: number, header: string, value: string) => {
    const newRows = data.rows.map((row, i) => {
      if (i !== rowIndex) return row;
      return { ...row, [header]: value };
    });
    onChange({ ...data, rows: newRows });
  };

  const updateHeader = (headerIndex: number, value: string) => {
    const oldHeader = data.headers[headerIndex];
    const newHeaders = data.headers.map((h, i) =>
      i === headerIndex ? value : h,
    );
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      data.headers.forEach((h, i) => {
        const key = i === headerIndex ? value : h;
        newRow[key] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void oldHeader;
  };

  const addRow = () => {
    const emptyRow: Record<string, string> = {};
    data.headers.forEach((h) => {
      emptyRow[h] = "";
    });
    onChange({ ...data, rows: [...data.rows, emptyRow] });
  };

  const removeRow = (rowIndex: number) => {
    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
  };

  const addColumn = () => {
    const newHeader = `Column ${data.headers.length + 1}`;
    const newHeaders = [...data.headers, newHeader];
    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
    onChange({ ...data, headers: newHeaders, rows: newRows });
  };

  const removeColumn = (headerIndex: number) => {
    if (data.headers.length <= 1) return;
    const removedHeader = data.headers[headerIndex];
    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
    const newRows = data.rows.map((row) => {
      const newRow: Record<string, string> = {};
      newHeaders.forEach((h) => {
        newRow[h] = row[h] ?? "";
      });
      return newRow;
    });
    onChange({ ...data, headers: newHeaders, rows: newRows });
    void removedHeader;
  };

  const toggleUnit = (unit: string) => {
    onChange({ ...data, units: { ...data.units, default: unit } });
  };

  return (
    <div>
      {/* Toolbar — unit toggle + row/col count */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: "8px",
          marginBottom: "10px",
        }}
      >
        <span
          style={{
            fontSize: "12px",
            fontWeight: 600,
            color: "#6d7175",
            textTransform: "uppercase",
            letterSpacing: "0.04em",
          }}
        >
          Units
        </span>
        <div
          style={{
            display: "flex",
            gap: "4px",
            background: "#f6f6f7",
            borderRadius: "20px",
            padding: "3px",
            border: "1px solid #e1e3e5",
          }}
        >
          {data.units.available.map((unit) => (
            <button
              key={unit}
              type="button"
              onClick={() => toggleUnit(unit)}
              style={{
                padding: "3px 14px",
                borderRadius: "16px",
                border: "none",
                background:
                  data.units.default === unit ? "#2c6ecb" : "transparent",
                color: data.units.default === unit ? "#ffffff" : "#6d7175",
                fontWeight: data.units.default === unit ? 700 : 500,
                cursor: "pointer",
                fontSize: "12px",
                lineHeight: "20px",
                transition: "all 0.12s ease",
                fontFamily: "inherit",
              }}
            >
              {unit}
            </button>
          ))}
        </div>
        <div
          style={{
            marginLeft: "auto",
            fontSize: "12px",
            color: "#8c9196",
            fontWeight: 500,
            background: "#f6f6f7",
            border: "1px solid #e1e3e5",
            borderRadius: "6px",
            padding: "3px 10px",
          }}
        >
          {data.rows.length} rows &middot; {data.headers.length} cols
        </div>
      </div>

      {/* Table */}
      <div
        style={{
          border: "1px solid #e1e3e5",
          borderRadius: "8px",
          overflow: "hidden",
          overflowX: "auto",
        }}
      >
        <table
          style={{
            width: "100%",
            borderCollapse: "collapse",
            fontSize: "13px",
            tableLayout: "auto",
          }}
        >
          <thead>
            <tr>
              {data.headers.map((header, hi) => (
                <th
                  key={hi}
                  style={{
                    background: "#f6f6f7",
                    borderBottom: "2px solid #e1e3e5",
                    borderRight:
                      hi < data.headers.length - 1
                        ? "1px solid #e1e3e5"
                        : "none",
                    padding: "0",
                    position: "relative",
                    minWidth: "110px",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      alignItems: "center",
                      padding: "2px 6px 2px 10px",
                    }}
                  >
                    <input
                      ref={(el) => {
                        headerInputRefs.current[hi] = el;
                      }}
                      value={header}
                      onChange={(e) =>
                        updateHeader(hi, (e.target as HTMLInputElement).value)
                      }
                      style={{
                        flex: 1,
                        border: "none",
                        background: "transparent",
                        fontWeight: 700,
                        fontSize: "12px",
                        color: "#202223",
                        padding: "8px 4px",
                        outline: "none",
                        minWidth: "60px",
                        textTransform: "uppercase",
                        letterSpacing: "0.04em",
                        fontFamily: "inherit",
                      }}
                      placeholder={`Col ${hi + 1}`}
                    />
                    {data.headers.length > 1 && (
                      <button
                        type="button"
                        onClick={() => removeColumn(hi)}
                        title="Remove column"
                        style={{
                          background: "none",
                          border: "none",
                          cursor: "pointer",
                          color: "#c9cccf",
                          padding: "2px 4px",
                          borderRadius: "4px",
                          fontSize: "15px",
                          lineHeight: 1,
                          flexShrink: 0,
                          transition: "color 0.1s, background 0.1s",
                          fontFamily: "inherit",
                        }}
                        onMouseEnter={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#d82c0d";
                          (
                            e.currentTarget as HTMLButtonElement
                          ).style.background = "#fee2e2";
                        }}
                        onMouseLeave={(e) => {
                          (e.currentTarget as HTMLButtonElement).style.color =
                            "#c9cccf";
                          (
                            e.currentTarget as HTMLButtonElement
                          ).style.background = "none";
                        }}
                      >
                        &times;
                      </button>
                    )}
                  </div>
                </th>
              ))}

              {/* Add column header cell */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  padding: "0",
                  width: "40px",
                  minWidth: "40px",
                }}
              >
                <button
                  type="button"
                  onClick={addColumn}
                  title="Add column"
                  style={{
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "100%",
                    height: "100%",
                    minHeight: "38px",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "20px",
                    lineHeight: 1,
                    padding: "0",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  +
                </button>
              </th>

              {/* Row actions header spacer */}
              <th
                style={{
                  background: "#f6f6f7",
                  borderBottom: "2px solid #e1e3e5",
                  width: "36px",
                  minWidth: "36px",
                }}
              />
            </tr>
          </thead>
          <tbody>
            {data.rows.map((row, ri) => (
              <tr
                key={ri}
                style={{
                  background: ri % 2 === 0 ? "#ffffff" : "#fafbfb",
                  transition: "background 0.1s",
                }}
                onMouseEnter={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    "#f0f5ff";
                }}
                onMouseLeave={(e) => {
                  (e.currentTarget as HTMLTableRowElement).style.background =
                    ri % 2 === 0 ? "#ffffff" : "#fafbfb";
                }}
              >
                {data.headers.map((header, hi) => (
                  <td
                    key={hi}
                    style={{
                      borderBottom:
                        ri < data.rows.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      borderRight:
                        hi < data.headers.length - 1
                          ? "1px solid #e1e3e5"
                          : "none",
                      padding: "0",
                    }}
                  >
                    <input
                      value={row[header] ?? ""}
                      onChange={(e) =>
                        updateCell(
                          ri,
                          header,
                          (e.target as HTMLInputElement).value,
                        )
                      }
                      style={{
                        width: "100%",
                        border: "none",
                        background: "transparent",
                        padding: "9px 10px",
                        fontSize: "13px",
                        color: "#202223",
                        outline: "none",
                        boxSizing: "border-box",
                        fontFamily: "inherit",
                      }}
                      onFocus={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow =
                          "inset 0 0 0 2px #2c6ecb";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "#f0f5ff";
                      }}
                      onBlur={(e) => {
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.boxShadow = "none";
                        (
                          e.target as HTMLInputElement
                        ).parentElement!.style.background = "transparent";
                      }}
                      placeholder="—"
                    />
                  </td>
                ))}

                {/* Column spacer — aligns under add column button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    borderRight: "1px solid #e1e3e5",
                    width: "40px",
                    background: "transparent",
                  }}
                />

                {/* Remove row button */}
                <td
                  style={{
                    borderBottom:
                      ri < data.rows.length - 1 ? "1px solid #e1e3e5" : "none",
                    padding: "0",
                    textAlign: "center",
                    width: "36px",
                    background: "transparent",
                  }}
                >
                  <button
                    type="button"
                    onClick={() => removeRow(ri)}
                    title="Remove row"
                    style={{
                      background: "none",
                      border: "none",
                      cursor: "pointer",
                      color: "#c9cccf",
                      fontSize: "16px",
                      lineHeight: 1,
                      padding: "4px 8px",
                      borderRadius: "4px",
                      transition: "color 0.1s, background 0.1s",
                      fontFamily: "inherit",
                    }}
                    onMouseEnter={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#d82c0d";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "#fee2e2";
                    }}
                    onMouseLeave={(e) => {
                      (e.currentTarget as HTMLButtonElement).style.color =
                        "#c9cccf";
                      (e.currentTarget as HTMLButtonElement).style.background =
                        "none";
                    }}
                  >
                    &times;
                  </button>
                </td>
              </tr>
            ))}

            {/* Add row footer */}
            <tr>
              <td
                colSpan={data.headers.length + 2}
                style={{
                  padding: "0",
                  background: "#f6f6f7",
                  borderTop: "1px solid #e1e3e5",
                }}
              >
                <button
                  type="button"
                  onClick={addRow}
                  style={{
                    display: "block",
                    width: "100%",
                    background: "none",
                    border: "none",
                    cursor: "pointer",
                    color: "#2c6ecb",
                    fontSize: "13px",
                    fontWeight: 600,
                    padding: "10px 14px",
                    textAlign: "left",
                    transition: "background 0.1s",
                    fontFamily: "inherit",
                  }}
                  onMouseEnter={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "#e8f0fe";
                  }}
                  onMouseLeave={(e) => {
                    (e.currentTarget as HTMLButtonElement).style.background =
                      "none";
                  }}
                >
                  + Add row
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

