export default function WidgetCustomizer() {
  const { config: serverConfig } = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();
  const navigate = useNavigate();

  const [config, setConfig] = useState<LocalConfig>({
    displayMode: serverConfig.displayMode,
    position: serverConfig.position,
    triggerType: serverConfig.triggerType,
    primaryColor: serverConfig.primaryColor,
    successColor: serverConfig.successColor,
    errorColor: serverConfig.errorColor,
    backgroundColor: serverConfig.backgroundColor,
    textColor: serverConfig.textColor,
    borderRadius: serverConfig.borderRadius,
    heading: serverConfig.heading,
    placeholder: serverConfig.placeholder,
    buttonText: serverConfig.buttonText,
    successMessage: serverConfig.successMessage,
    errorMessage: serverConfig.errorMessage,
    showRecommender: serverConfig.showRecommender,
    customCss: serverConfig.customCss,
  });

  const isLoading = fetcher.state !== "idle";

  useEffect(() => {
    if (fetcher.data && "ok" in fetcher.data) {
      shopify.toast.show(fetcher.data.message ?? "Widget settings saved");
    } else if (fetcher.data && "error" in fetcher.data) {
      shopify.toast.show(fetcher.data.error ?? "Failed to save settings", { isError: true });
    }
  }, [fetcher.data, shopify]);

  const updateConfig = (key: keyof LocalConfig, value: string | boolean) => {
    setConfig((prev) => ({ ...prev, [key]: value }));
  };

  const handleSave = () => {
    const formData = new FormData();
    formData.set("displayMode", config.displayMode);
    formData.set("position", config.position);
    formData.set("triggerType", config.triggerType);
    formData.set("primaryColor", config.primaryColor);
    formData.set("successColor", config.successColor);
    formData.set("errorColor", config.errorColor);
    formData.set("backgroundColor", config.backgroundColor);
    formData.set("textColor", config.textColor);
    formData.set("borderRadius", config.borderRadius);
    formData.set("heading", config.heading);
    formData.set("placeholder", config.placeholder);
    formData.set("buttonText", config.buttonText);
    formData.set("successMessage", config.successMessage);
    formData.set("errorMessage", config.errorMessage);
    formData.set("showRecommender", config.showRecommender ? "true" : "false");
    formData.set("customCss", config.customCss);
    fetcher.submit(formData, { method: "post" });
  };

  const showPosition = config.displayMode === "popup" || config.displayMode === "both";

  return (
    <Page
      title="Widget Customizer"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={
        <Button variant="primary" onClick={handleSave} loading={isLoading}>
          Save changes
        </Button>
      }
    >
      <Layout>
        <Layout.Section>
          <BlockStack gap="600">

            {/* ---------------------------------------------------------------- */}
            {/* Section 1 — Display Mode                                         */}
            {/* ---------------------------------------------------------------- */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Display Mode</Text>
                <InlineStack gap="400" wrap>
                  <DisplayModeCard
                    value="popup"
                    label="Popup"
                    description="Opens as a modal overlay when triggered"
                    benefit="clean product pages"
                    selected={config.displayMode === "popup"}
                    onSelect={(v) => updateConfig("displayMode", v)}
                  />
                  <DisplayModeCard
                    value="inline"
                    label="Inline"
                    description="Embedded directly in the product page"
                    benefit="detailed size info"
                    selected={config.displayMode === "inline"}
                    onSelect={(v) => updateConfig("displayMode", v)}
                  />
                  <DisplayModeCard
                    value="both"
                    label="Both"
                    description="Inline summary with popup for full chart"
                    benefit="maximum visibility"
                    selected={config.displayMode === "both"}
                    onSelect={(v) => updateConfig("displayMode", v)}
                  />
                </InlineStack>
              </BlockStack>
            </Card>

            {/* ---------------------------------------------------------------- */}
            {/* Section 2 — Trigger Settings                                     */}
            {/* ---------------------------------------------------------------- */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Trigger Settings</Text>
                <BlockStack gap="400">
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">Trigger style</Text>
                    <TriggerTypeSelector
                      value={config.triggerType}
                      onChange={(v) => updateConfig("triggerType", v)}
                    />
                  </BlockStack>

                  {showPosition && (
                    <BlockStack gap="200">
                      <Text as="p" variant="bodyMd">Popup position</Text>
                      <PositionGrid
                        value={config.position}
                        onChange={(v) => updateConfig("position", v)}
                      />
                    </BlockStack>
                  )}
                </BlockStack>
              </BlockStack>
            </Card>

            {/* ---------------------------------------------------------------- */}
            {/* Section 3 — Colors                                               */}
            {/* ---------------------------------------------------------------- */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Colors</Text>
                <InlineStack gap="400" wrap>
                  <ColorPickerField
                    label="Primary Color"
                    value={config.primaryColor}
                    onChange={(v) => updateConfig("primaryColor", v)}
                  />
                  <ColorPickerField
                    label="Background Color"
                    value={config.backgroundColor}
                    onChange={(v) => updateConfig("backgroundColor", v)}
                  />
                  <ColorPickerField
                    label="Text Color"
                    value={config.textColor}
                    onChange={(v) => updateConfig("textColor", v)}
                  />
                  <ColorPickerField
                    label="Success Color"
                    value={config.successColor}
                    onChange={(v) => updateConfig("successColor", v)}
                  />
                  <ColorPickerField
                    label="Error Color"
                    value={config.errorColor}
                    onChange={(v) => updateConfig("errorColor", v)}
                  />
                </InlineStack>
              </BlockStack>
            </Card>

            {/* ---------------------------------------------------------------- */}
            {/* Section 4 — Typography & Spacing                                 */}
            {/* ---------------------------------------------------------------- */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Typography &amp; Spacing</Text>
                <BlockStack gap="200">
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd">Border Radius (px)</Text>
                    <InlineStack gap="400" blockAlign="center">
                      <div style={{ flex: 1 }}>
                        <input
                          type="range"
                          min="0"
                          max="24"
                          value={config.borderRadius}
                          onChange={(e) => updateConfig("borderRadius", e.target.value)}
                          style={{ width: "100%", accentColor: "#005bd3", cursor: "pointer" }}
                        />
                      </div>
                      <input
                        type="number"
                        min="0"
                        max="24"
                        value={config.borderRadius}
                        onChange={(e) => updateConfig("borderRadius", e.target.value)}
                        style={{
                          width: "60px",
                          padding: "8px 12px",
                          border: "1px solid #8c9196",
                          borderRadius: "8px",
                          fontSize: "14px",
                          outline: "none",
                          boxSizing: "border-box" as const,
                          fontFamily: "inherit",
                          color: "#202223",
                          backgroundColor: "#fff",
                        }}
                      />
                    </InlineStack>
                  </BlockStack>

                  {/* Border radius preset swatches */}
                  <InlineStack gap="400" blockAlign="center">
                    {["0", "4", "8", "12", "24"].map((r) => (
                      <div key={r} onClick={() => updateConfig("borderRadius", r)} style={{ cursor: "pointer" }}>
                        <div
                          title={`${r}px`}
                          style={{
                            width: "40px",
                            height: "40px",
                            backgroundColor: config.borderRadius === r ? config.primaryColor : "#e3e5e7",
                            borderRadius: `${r}px`,
                            cursor: "pointer",
                            transition: "all 0.15s",
                            border: config.borderRadius === r
                              ? `2px solid ${config.primaryColor}`
                              : "2px solid transparent",
                          }}
                        />
                      </div>
                    ))}
                    <Text as="p" variant="bodyMd" tone="subdued">{config.borderRadius}px</Text>
                  </InlineStack>
                </BlockStack>
              </BlockStack>
            </Card>

            {/* ---------------------------------------------------------------- */}
            {/* Section 5 — Text & Messages                                      */}
            {/* ---------------------------------------------------------------- */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Text &amp; Messages</Text>
                <BlockStack gap="400">

                  <TextField
                    label="Widget Heading"
                    value={config.heading}
                    onChange={(value) => updateConfig("heading", value)}
                    placeholder="Size Guide"
                    autoComplete="off"
                  />

                  <TextField
                    label="Button Text"
                    value={config.buttonText}
                    onChange={(value) => updateConfig("buttonText", value)}
                    placeholder="Find My Size"
                    autoComplete="off"
                  />

                  <TextField
                    label="Placeholder Text"
                    value={config.placeholder}
                    onChange={(value) => updateConfig("placeholder", value)}
                    placeholder="Select your size"
                    autoComplete="off"
                  />

                  <BlockStack gap="200">
                    <TextField
                      label="Success Message"
                      value={config.successMessage}
                      onChange={(value) => updateConfig("successMessage", value)}
                      placeholder="This size should fit you well!"
                      autoComplete="off"
                    />
                    <Text as="p" variant="bodyMd" tone="subdued">Shown after a successful size recommendation</Text>
                  </BlockStack>

                  <BlockStack gap="200">
                    <TextField
                      label="Error Message"
                      value={config.errorMessage}
                      onChange={(value) => updateConfig("errorMessage", value)}
                      placeholder="We couldn't determine your size. Please refer to the chart."
                      autoComplete="off"
                    />
                    <Text as="p" variant="bodyMd" tone="subdued">Shown when a recommendation cannot be made</Text>
                  </BlockStack>

                </BlockStack>
              </BlockStack>
            </Card>

            {/* ---------------------------------------------------------------- */}
            {/* Section 6 — Features                                             */}
            {/* ---------------------------------------------------------------- */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Features</Text>
                <BlockStack gap="400">

                  <Card>
                    <BlockStack gap="200">
                      <Checkbox
                        label="Show AI Recommender"
                        checked={config.showRecommender}
                        onChange={(checked) => updateConfig("showRecommender", checked)}
                        helpText='Display the "Find My Size" button that lets customers get a personalized size recommendation based on their measurements.'
                      />
                      {config.showRecommender && (
                        <Badge tone="success">Enabled</Badge>
                      )}
                    </BlockStack>
                  </Card>

                  <Card>
                    <BlockStack gap="200">
                      <Text as="h2" variant="headingMd" fontWeight="bold">Custom CSS</Text>
                      <Text as="p" variant="bodyMd" tone="subdued">
                        Advanced: inject custom styles directly into the widget. Use sparingly.
                      </Text>
                      <textarea
                        value={config.customCss}
                        onChange={(e) => updateConfig("customCss", e.target.value)}
                        rows={6}
                        placeholder={`.size-chart-widget {\n  /* custom styles */\n}`}
                        style={{
                          width: "100%",
                          padding: "8px 12px",
                          border: "1px solid #8c9196",
                          borderRadius: "8px",
                          fontFamily: "'Courier New', Courier, monospace",
                          fontSize: "12px",
                          resize: "vertical",
                          minHeight: "120px",
                          outline: "none",
                          boxSizing: "border-box" as const,
                          color: "#202223",
                          backgroundColor: "#fff",
                        }}
                      />
                    </BlockStack>
                  </Card>

                </BlockStack>
              </BlockStack>
            </Card>

            {/* ================================================================ */}
            {/* LIVE PREVIEW — inline, full width                                 */}
            {/* ================================================================ */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Live Preview</Text>
                <BlockStack gap="400">
                  <InlineStack gap="400" align="space-between" blockAlign="center">
                    <Text as="p" variant="bodyMd" tone="subdued">Updates instantly as you change settings</Text>
                    <InlineStack gap="200">
                      <Badge tone="info">{config.displayMode}</Badge>
                      <Badge tone="info">{config.triggerType}</Badge>
                      {showPosition && <Badge tone="info">{config.position}</Badge>}
                      <Badge tone={config.showRecommender ? "success" : "info"}>
                        {`AI ${config.showRecommender ? "On" : "Off"}`}
                      </Badge>
                    </InlineStack>
                  </InlineStack>
                  <Divider />
                  <div style={{ display: "flex", justifyContent: "center", padding: "16px 0" }}>
                    <WidgetPreview config={config} />
                  </div>
                </BlockStack>
              </BlockStack>
            </Card>

          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

