1477→    if (!config.showRecommender) {
1478→      if (tabRec)   tabRec.setAttribute('hidden', '');
1479→      if (panelRec) panelRec.setAttribute('hidden', '');
1480→    } else {
1481→      if (tabRec)   tabRec.removeAttribute('hidden');
1482→    }
1483→    // Display mode
1484→    var mode = config.displayMode || displayMode;
1485→    if ((mode === 'inline' || mode === 'both') && inlineWrap) {
1486→      inlineWrap.style.display = '';
1487→      loadInline();
1488→    }
1489→    // Render trigger for popup/both modes
