225→function FunnelBar({ rate, color }: { rate: number; color: string }) {
226→  return (
227→    <div style={{ height: "6px", background: "#e4e5e7", borderRadius: "3px", overflow: "hidden", marginTop: "4px" }}>
228→      <div
229→        style={{
230→          height: "100%",
231→          background: color,
232→          borderRadius: "3px",
233→          width: `${Math.min(100, rate)}%`,
234→          transition: "width 0.3s ease",
235→        }}
236→      />
237→    </div>
238→  );
239→}
