 23→// ---------------------------------------------------------------------------
 24→
 25→interface DailyDataPoint {
 26→  label: string;
 27→  value: number;
 28→}
 29→
 30→interface TopChart {
 31→  chartId: string | null;
 32→  chartName: string;
 33→  views: number;
 34→  rank: number;
