function StepCircle({ done }: { done: boolean }) {
  return (
    <div
      style={{
        width: "24px",
        height: "24px",
        borderRadius: "50%",
        border: done ? "none" : "2px solid #8a8a8a",
        background: done ? "#303030" : "transparent",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        flexShrink: 0,
        color: "#fff",
        fontSize: "13px",
        fontWeight: 700,
      }}
    >
      {done && "✓"}
    </div>
  );
}

input.new_string:
function StepCircle({ done }: { done: boolean }) {
  return (
    <Box
      width="24px"
      minHeight="24px"
      borderRadius="full"
      borderWidth={done ? "0" : "025"}
      borderColor={done ? undefined : "border"}
      background={done ? "bg-fill-emphasis" : "bg-surface"}
    >
      <InlineStack align="center" blockAlign="center">
        {done && (
          <Text as="span" variant="bodySm" fontWeight="bold" tone="text-inverse">
            ✓
          </Text>
        )}
      </InlineStack>
    </Box>
  );
}

