 8→export type Primitive = null | undefined | string | number | boolean | symbol | bigint;
 9→/**
10→ * Gets keys from a type. Similar to `keyof` but this one also works for union types.
11→ * The reason a simple `keyof Union` does not work is because `keyof` always returns the accessible keys of a type.
12→ * In the case of a union, that will only be the common keys.
13→ * @link https://stackoverflow.com/a/49402091
14→ */
15→export type KeysOfUnion<T> = T extends T ? keyof T : never;
16→/**
17→ * Create a type that does not allow extra properties, meaning it only allows properties that are explicitly declared.
18→ *
