function BarChart({ data }: { data: DailyDataPoint[] }) {
  const max = Math.max(...data.map((d) => d.value), 1);
  return (
    <div style={{ display: "flex", alignItems: "flex-end", gap: "2px", height: "120px" }}>
      {data.map((d, i) => (
        <Tooltip key={i} content={`${d.label}: ${d.value} views`}>
          <Box minHeight="100%" width="100%">
            <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", height: "120px", justifyContent: "flex-end" }}>
              <Box
                width="100%"
                background="bg-fill-brand"
                borderStartStartRadius="050"
                borderStartEndRadius="050"
                minHeight={d.value > 0 ? "2px" : "0"}
              >
                <div style={{ height: `${Math.max((d.value / max) * 120, d.value > 0 ? 2 : 0)}px` }} />
              </Box>
            </div>
          </Box>
        </Tooltip>
      ))}
    </div>
  );
}

