204→          <Box minHeight="100%" width="100%">
205→            <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", height: "120px", justifyContent: "flex-end" }}>
206→              <Box
207→                width="100%"
208→                background="bg-fill-brand"
209→                borderStartStartRadius="050"
210→                borderStartEndRadius="050"
211→                minHeight={d.value > 0 ? "2px" : "0"}
212→              >
213→                <div style={{ height: `${Math.max((d.value / max) * 120, d.value > 0 ? 2 : 0)}px` }} />
214→              </Box>
215→            </div>
216→          </Box>
217→        </Tooltip>
218→      ))}
219→    </div>
220→  );
