import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData, useFetcher, useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
  ButtonGroup,
  Banner,
  Box,
  InlineGrid,
  Tooltip,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan, hasFeature } from "../lib/plans";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface DailyDataPoint {
  label: string;
  value: number;
}

interface TopChart {
  chartId: string | null;
  chartName: string;
  views: number;
  rank: number;
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const url = new URL(request.url);
  const fromParam = url.searchParams.get("from");
  const toParam = url.searchParams.get("to");
  const presetParam = url.searchParams.get("preset") ?? "30d";

  // Resolve date range
  const now = new Date();
  let fromDate: Date;
  let toDate: Date = new Date(now);
  toDate.setHours(23, 59, 59, 999);

  if (fromParam && toParam) {
    fromDate = new Date(fromParam);
    fromDate.setHours(0, 0, 0, 0);
    const parsedTo = new Date(toParam);
    parsedTo.setHours(23, 59, 59, 999);
    toDate = parsedTo;
  } else {
    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
    fromDate.setHours(0, 0, 0, 0);
  }

  const dateFilter = { gte: fromDate, lte: toDate };

  const subscription = await db.subscription.findUnique({ where: { shop } });
  const plan = getPlan(subscription?.planId ?? "free");
  const canViewAnalytics = hasFeature(plan.id, "analytics");

  if (!canViewAnalytics) {
    return {
      plan,
      canViewAnalytics: false as const,
      stats: null,
      topChartsWithNames: [] as TopChart[],
      dailyTrend: [] as DailyDataPoint[],
      preset: presetParam,
      fromDate: fromDate.toISOString().split("T")[0],
      toDate: toDate.toISOString().split("T")[0],
    };
  }

  const [
    totalViews,
    totalClicks,
    totalRecommendations,
    totalConverts,
    topCharts,
    rawEvents,
  ] = await Promise.all([
    db.analyticsEvent.count({ where: { shop, eventType: "view", createdAt: dateFilter } }),
    db.analyticsEvent.count({ where: { shop, eventType: "click", createdAt: dateFilter } }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend", createdAt: dateFilter } }),
    db.analyticsEvent.count({ where: { shop, eventType: "convert", createdAt: dateFilter } }),
    db.analyticsEvent.groupBy({
      by: ["sizeChartId"],
      where: { shop, eventType: "view", sizeChartId: { not: null }, createdAt: dateFilter },
      _count: { id: true },
      orderBy: { _count: { id: "desc" } },
      take: 5,
    }),
    db.analyticsEvent.findMany({
      where: { shop, eventType: "view", createdAt: dateFilter },
      select: { createdAt: true },
      orderBy: { createdAt: "asc" },
    }),
  ]);

  // Build daily trend bucketed by day
  const dayBuckets: Record<string, number> = {};
  const diffMs = toDate.getTime() - fromDate.getTime();
  const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
  for (let i = 0; i < Math.min(diffDays, 90); i++) {
    const d = new Date(fromDate.getTime() + i * 24 * 60 * 60 * 1000);
    const key = d.toISOString().split("T")[0];
    dayBuckets[key] = 0;
  }
  for (const ev of rawEvents) {
    const key = ev.createdAt.toISOString().split("T")[0];
    if (key in dayBuckets) dayBuckets[key]++;
  }

  // Condense to max 30 bars for readability
  const bucketEntries = Object.entries(dayBuckets);
  const maxBars = 30;
  let dailyTrend: DailyDataPoint[];
  if (bucketEntries.length <= maxBars) {
    dailyTrend = bucketEntries.map(([date, value]) => ({
      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
      value,
    }));
  } else {
    // Group into weekly buckets
    const weekBuckets: Record<string, number> = {};
    for (const [date, count] of bucketEntries) {
      const d = new Date(date + "T12:00:00Z");
      const weekStart = new Date(d);
      weekStart.setDate(d.getDate() - d.getDay());
      const wk = weekStart.toISOString().split("T")[0];
      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + count;
    }
    dailyTrend = Object.entries(weekBuckets).map(([date, value]) => ({
      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
      value,
    }));
  }

  // Resolve chart names
  const chartIds = topCharts.map((tc) => tc.sizeChartId).filter((id): id is string => id !== null);
  const charts = chartIds.length > 0
    ? await db.sizeChart.findMany({ where: { id: { in: chartIds }, shop }, select: { id: true, name: true } })
    : [];

  const topChartsWithNames: TopChart[] = topCharts.map((tc, idx) => ({
    chartId: tc.sizeChartId,
    chartName: charts.find((c) => c.id === tc.sizeChartId)?.name ?? "Unknown",
    views: tc._count.id,
    rank: idx + 1,
  }));

  // Funnel rates
  const clickRate = totalViews > 0 ? ((totalClicks / totalViews) * 100).toFixed(1) : "0";
  const recommendRate = totalClicks > 0 ? ((totalRecommendations / totalClicks) * 100).toFixed(1) : "0";
  const convertRate = totalRecommendations > 0 ? ((totalConverts / totalRecommendations) * 100).toFixed(1) : "0";
  const overallConvertRate = totalViews > 0 ? ((totalConverts / totalViews) * 100).toFixed(1) : "0";

  return {
    plan,
    canViewAnalytics: true as const,
    stats: {
      totalViews,
      totalClicks,
      totalRecommendations,
      totalConverts,
      clickRate,
      recommendRate,
      convertRate,
      overallConvertRate,
    },
    topChartsWithNames,
    dailyTrend,
    preset: presetParam,
    fromDate: fromDate.toISOString().split("T")[0],
    toDate: toDate.toISOString().split("T")[0],
  };
};

// ---------------------------------------------------------------------------
// BarChart sub-component (custom visualization — minimal inline styles)
// ---------------------------------------------------------------------------

function BarChart({ data }: { data: DailyDataPoint[] }) {
  const max = Math.max(...data.map((d) => d.value), 1);
  return (
    <div style={{ display: "flex", alignItems: "flex-end", gap: "2px", height: "120px" }}>
      {data.map((d, i) => (
        <Tooltip key={i} content={`${d.label}: ${d.value} views`}>
          <Box minHeight="100%" width="100%">
            <div style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", height: "120px", justifyContent: "flex-end" }}>
              <Box
                width="100%"
                background="bg-fill-brand"
                borderStartStartRadius="050"
                borderStartEndRadius="050"
                minHeight={d.value > 0 ? "2px" : "0"}
              >
                <div style={{ height: `${Math.max((d.value / max) * 120, d.value > 0 ? 2 : 0)}px` }} />
              </Box>
            </div>
          </Box>
        </Tooltip>
      ))}
    </div>
  );
}

// ---------------------------------------------------------------------------
// FunnelBar sub-component (inline style — custom visualization)
// ---------------------------------------------------------------------------

function FunnelBar({ rate, color }: { rate: number; color: string }) {
  return (
    <Box background="bg-fill-secondary" borderRadius="150" overflowX="hidden" minHeight="6px">
      <div
        style={{
          height: "6px",
          background: color,
          borderRadius: "var(--p-border-radius-150)",
          width: `${Math.min(100, rate)}%`,
          transition: "width 0.3s ease",
        }}
      />
    </Box>
  );
}

// ---------------------------------------------------------------------------
// RankBadge sub-component
// ---------------------------------------------------------------------------

function RankBadge({ rank }: { rank: number }) {
  const toneMap: Record<number, { bg: "bg-fill-caution" | "bg-fill-secondary" | "bg-fill-warning"; text: "text" }> = {
    1: { bg: "bg-fill-caution", text: "text" },
    2: { bg: "bg-fill-secondary", text: "text" },
    3: { bg: "bg-fill-warning", text: "text" },
  };
  const tone = toneMap[rank];
  return (
    <Box
      background={tone?.bg ?? "bg-fill-secondary"}
      borderRadius="full"
      minWidth="28px"
      minHeight="28px"
      width="28px"
    >
      <div
        style={{
          width: "28px",
          height: "28px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <Text as="span" variant="bodySm" fontWeight="bold" tone={rank <= 3 ? undefined : "subdued"}>
          {String(rank)}
        </Text>
      </div>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const PRESET_OPTIONS = [
  { label: "7 days", value: "7d" },
  { label: "30 days", value: "30d" },
  { label: "90 days", value: "90d" },
];

export default function Analytics() {
  const loaderData = useLoaderData<typeof loader>();
  const fetcher = useFetcher<typeof loader>();
  const navigate = useNavigate();
  const [activePreset, setActivePreset] = useState(loaderData.preset ?? "30d");

  // Use fetcher data when available (after date range change), else loader data
  const data = fetcher.data ?? loaderData;
  const isLoading = fetcher.state !== "idle";

  function handlePreset(preset: string) {
    setActivePreset(preset);
    fetcher.load(`/app/analytics?preset=${preset}`);
  }

  // Gate check — use loaderData since data might be the fetcher result
  if (!data.canViewAnalytics) {
    return (
      <Page
        title="Analytics"
        backAction={{ onAction: () => navigate("/app") }}
      >
        <Layout>
          <Layout.Section>
            <BlockStack gap="600">
              <Banner tone="warning" title="Analytics is a Growth plan feature">
                <BlockStack gap="400">
                  <Text as="p" variant="bodyMd">
                    Track how customers interact with your size charts. See chart views, click-through rates,
                    AI recommendation usage, and conversion impact — all in one dashboard.
                  </Text>
                  <InlineStack gap="400">
                    <Button variant="primary" url="/app/pricing">Upgrade to Growth — $9.99/mo</Button>
                    <Button url="/app/pricing">Compare all plans</Button>
                  </InlineStack>
                </BlockStack>
              </Banner>

              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">What you&apos;ll unlock</Text>
                  <InlineGrid columns={{ xs: 1, sm: 2, md: 3 }} gap="400">
                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">Chart Views</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">See exactly how many customers open your size charts by product and date range.</Text>
                      </BlockStack>
                    </Card>
                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">Conversion Funnel</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Measure the path from chart view to AI recommendation to add-to-cart.</Text>
                      </BlockStack>
                    </Card>
                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingMd" fontWeight="bold">Top Charts</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Identify which size charts drive the most customer engagement.</Text>
                      </BlockStack>
                    </Card>
                  </InlineGrid>
                </BlockStack>
              </Card>
            </BlockStack>
          </Layout.Section>
        </Layout>
      </Page>
    );
  }

  const { stats, topChartsWithNames, dailyTrend } = data;
  const hasData = stats !== null && stats.totalViews > 0;
  const canViewReturnAttribution = hasFeature(data.plan.id, "returnAttribution");

  return (
    <Page
      title="Analytics"
      backAction={{ onAction: () => navigate("/app") }}
      primaryAction={
        <ButtonGroup variant="segmented">
          {PRESET_OPTIONS.map((opt) => (
            <Button
              key={opt.value}
              variant={activePreset === opt.value ? "primary" : undefined}
              onClick={() => handlePreset(opt.value)}
              disabled={isLoading}
            >
              {opt.label}
            </Button>
          ))}
        </ButtonGroup>
      }
    >
      <Layout>
        <Layout.Section>
          <BlockStack gap="600">

            {/* ================================================================ */}
            {/* UPGRADE BANNER — return attribution (Pro feature)               */}
            {/* ================================================================ */}
            {!canViewReturnAttribution && hasData && (
              <Banner tone="info" title="Unlock Return Attribution — Pro plan">
                <InlineStack gap="400" blockAlign="center">
                  <Text as="p" variant="bodyMd">
                    Connect size chart interactions directly to return rates. See exactly how much revenue your size charts protect.
                  </Text>
                  <Button url="/app/pricing">Upgrade to Pro</Button>
                </InlineStack>
              </Banner>
            )}

            {/* ================================================================ */}
            {/* EMPTY STATE                                                       */}
            {/* ================================================================ */}
            {!hasData && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">No data yet for this period</Text>
                  <Text as="p" variant="bodyMd" tone="subdued">
                    Analytics data appears as soon as customers start viewing your size charts on your storefront.
                    Make sure your widget is enabled and a size chart is assigned to at least one product.
                  </Text>
                  <InlineStack gap="400">
                    <Button variant="primary" url="/app/size-charts">Manage size charts</Button>
                    <Button url="/app/widget">Check widget settings</Button>
                  </InlineStack>
                </BlockStack>
              </Card>
            )}

            {/* ================================================================ */}
            {/* STATS OVERVIEW CARDS                                             */}
            {/* ================================================================ */}
            {stats !== null && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">Overview</Text>
                  <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingLg" fontWeight="bold">{isLoading ? "—" : stats.totalViews.toLocaleString()}</Text>
                        <Text as="p" variant="bodyMd">Total Views</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Size chart opens</Text>
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingLg" fontWeight="bold">{isLoading ? "—" : stats.totalClicks.toLocaleString()}</Text>
                        <Text as="p" variant="bodyMd">Interactions</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Clicks within chart</Text>
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingLg" fontWeight="bold">{isLoading ? "—" : stats.totalRecommendations.toLocaleString()}</Text>
                        <Text as="p" variant="bodyMd">AI Recommendations</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Sizes suggested by AI</Text>
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <Text as="h2" variant="headingLg" fontWeight="bold">{isLoading ? "—" : stats.totalConverts.toLocaleString()}</Text>
                        <Text as="p" variant="bodyMd">Conversions</Text>
                        <Text as="p" variant="bodyMd" tone="subdued">Add-to-cart after chart</Text>
                      </BlockStack>
                    </Card>
                  </InlineGrid>
                </BlockStack>
              </Card>
            )}

            {/* ================================================================ */}
            {/* DAILY TREND CHART                                                */}
            {/* ================================================================ */}
            {hasData && dailyTrend.length > 0 && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">Daily Views Trend</Text>
                  <BlockStack gap="200">
                    <Text as="p" variant="bodyMd" tone="subdued">Chart views per day across the selected period</Text>
                    <BarChart data={dailyTrend} />
                    <InlineStack align="space-between">
                      <Text as="p" variant="bodyMd" tone="subdued">{dailyTrend[0]?.label ?? ""}</Text>
                      <Text as="p" variant="bodyMd" tone="subdued">{dailyTrend[dailyTrend.length - 1]?.label ?? ""}</Text>
                    </InlineStack>
                  </BlockStack>
                </BlockStack>
              </Card>
            )}

            {/* ================================================================ */}
            {/* CONVERSION FUNNEL                                                */}
            {/* ================================================================ */}
            {hasData && stats !== null && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">Conversion Funnel</Text>
                  <BlockStack gap="200">
                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Views → Interactions</Text>
                          <Badge tone={parseFloat(stats.clickRate) >= 20 ? "success" : "info"}>
                            {`${stats.clickRate}%`}
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {stats.totalClicks.toLocaleString()} of {stats.totalViews.toLocaleString()} chart viewers clicked inside
                        </Text>
                        <FunnelBar rate={parseFloat(stats.clickRate)} color="#005bd3" />
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Interactions → AI Recommendations</Text>
                          <Badge tone={parseFloat(stats.recommendRate) >= 30 ? "success" : "info"}>
                            {`${stats.recommendRate}%`}
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {stats.totalRecommendations.toLocaleString()} customers used the AI size recommender
                        </Text>
                        <FunnelBar rate={parseFloat(stats.recommendRate)} color="#2c7be5" />
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Recommendations → Conversions</Text>
                          <Badge tone={parseFloat(stats.convertRate) >= 40 ? "success" : "info"}>
                            {`${stats.convertRate}%`}
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          {stats.totalConverts.toLocaleString()} customers added to cart after receiving a recommendation
                        </Text>
                        <FunnelBar rate={parseFloat(stats.convertRate)} color="#1a73e8" />
                      </BlockStack>
                    </Card>

                    <Card>
                      <BlockStack gap="200">
                        <InlineStack align="space-between" blockAlign="center">
                          <Text as="p" variant="bodyMd">Overall: Views → Conversions</Text>
                          <Badge tone={parseFloat(stats.overallConvertRate) >= 5 ? "success" : "info"}>
                            {`${stats.overallConvertRate}%`}
                          </Badge>
                        </InlineStack>
                        <Text as="p" variant="bodyMd" tone="subdued">
                          End-to-end conversion rate — customers who viewed a chart and then added to cart
                        </Text>
                        <FunnelBar rate={parseFloat(stats.overallConvertRate) * 5} color="#16a34a" />
                      </BlockStack>
                    </Card>
                  </BlockStack>
                </BlockStack>
              </Card>
            )}

            {/* ================================================================ */}
            {/* TOP CHARTS BY VIEWS                                              */}
            {/* ================================================================ */}
            <Card>
              <BlockStack gap="400">
                <Text as="h2" variant="headingMd" fontWeight="bold">Top Size Charts</Text>
                {topChartsWithNames.length === 0 ? (
                  <Text as="p" variant="bodyMd" tone="subdued">
                    No chart views in this period. Data appears once customers start viewing your size charts.
                  </Text>
                ) : (
                  <BlockStack gap="200">
                    {topChartsWithNames.map((chart) => (
                      <Card key={chart.chartId ?? chart.rank}>
                        <InlineStack gap="400" blockAlign="center">
                          <RankBadge rank={chart.rank} />
                          <BlockStack gap="100">
                            <Button
                              variant="plain"
                              url={chart.chartId ? `/app/size-charts/${chart.chartId}` : "/app/size-charts"}
                            >
                              {chart.chartName}
                            </Button>
                            <Text as="p" variant="bodyMd" tone="subdued">{chart.views.toLocaleString()} view{chart.views !== 1 ? "s" : ""}</Text>
                          </BlockStack>
                        </InlineStack>
                      </Card>
                    ))}
                  </BlockStack>
                )}
              </BlockStack>
            </Card>

            {/* ================================================================ */}
            {/* INSIGHTS + UPSELL (inline)                                       */}
            {/* ================================================================ */}
            {hasData && stats !== null && (parseFloat(stats.clickRate) < 10 || parseFloat(stats.recommendRate) < 20) && (
              <Card>
                <BlockStack gap="400">
                  <Text as="h2" variant="headingMd" fontWeight="bold">Insights</Text>
                  <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
                    {parseFloat(stats.clickRate) < 10 && (
                      <Card>
                        <BlockStack gap="200">
                          <Badge tone="warning">Low click rate</Badge>
                          <Text as="p" variant="bodyMd" tone="subdued">
                            Below 10% — try moving your widget higher on the product page.
                          </Text>
                        </BlockStack>
                      </Card>
                    )}
                    {parseFloat(stats.recommendRate) < 20 && (
                      <Card>
                        <BlockStack gap="200">
                          <Badge tone="warning">AI underused</Badge>
                          <Text as="p" variant="bodyMd" tone="subdued">
                            Fewer than 20% of interactions use the AI recommender.
                          </Text>
                        </BlockStack>
                      </Card>
                    )}
                  </InlineGrid>
                </BlockStack>
              </Card>
            )}

            {!canViewReturnAttribution && (
              <Banner tone="info" title="Unlock Return Attribution">
                <InlineStack gap="400" blockAlign="center">
                  <Text as="p" variant="bodyMd">
                    See which charts reduce returns and calculate revenue saved. Available on Pro plan.
                  </Text>
                  <Button url="/app/pricing">Upgrade to Pro</Button>
                </InlineStack>
              </Banner>
            )}

          </BlockStack>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

