198→function BarChart({ data }: { data: DailyDataPoint[] }) {
199→  const max = Math.max(...data.map((d) => d.value), 1);
200→  return (
201→    <div style={{ display: "flex", alignItems: "flex-end", gap: "2px", height: "120px" }}>
