 530→  .scr-unit-label { font-size: .85rem; color: var(--scr-muted, #6b7280); }
 531→  .scr-unit-btn-group {
 532→    display: flex;
 533→    border: 1px solid var(--scr-border, #e5e7eb);
 534→    border-radius: 6px;
 535→    overflow: hidden;
 536→  }
 537→  .scr-unit-btn {
 538→    padding: .3em .85em;
 539→    font-size: .85rem;
 540→    font-weight: 500;
 541→    background: none;
 542→    border: none;
 543→    cursor: pointer;
 544→    color: var(--scr-muted, #6b7280);
