 701→      shopify.toast.show(data.message ?? "Saved");
 702→    } else if ("error" in data) {
 703→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 704→    }
 705→  }, [saveFetcher.data, shopify]);
 706→
 707→  // Status toggle feedback
