 37→interface TestResult {
 38→  size: string;
 39→  confidence: number;
 40→  alternatives: string[];
 41→  bust: number;
 42→  waist: number;
 43→  hips: number;
 44→}
 45→
 46→const DEFAULT_BODY_TYPES: BodyTypeConfig[] = [
 47→  { id: "slim", label: "Slim", description: "Narrower proportions, prefers fitted styles", enabled: true },
 48→  { id: "regular", label: "Regular", description: "Standard proportions, true-to-size fits well", enabled: true },
 49→  { id: "athletic", label: "Athletic", description: "Broader chest/shoulders, narrower waist", enabled: true },
 50→  { id: "plus", label: "Plus", description: "Fuller proportions, relaxed fit preferences", enabled: true },
 51→  { id: "petite", label: "Petite", description: "Shorter stature, petite-specific proportions", enabled: false },
 52→];
 53→
 54→const DEFAULT_FIT_PREFERENCE = "true-to-size";
 55→const DEFAULT_ALGORITHM = "basic";
