404→  const isLoading = fetcher.state !== "idle";
405→
406→  // Local state that mirrors the DB-loaded values
407→  const [enabled, setEnabled] = useState<boolean>(config.enabled);
408→  const [algorithm, setAlgorithm] = useState<string>(config.algorithm);
409→  const [bodyTypes, setBodyTypes] = useState<BodyTypeConfig[]>(initialBodyTypes);
410→  const [fitPreference, setFitPreference] = useState<string>(initialFitPreference);
411→  const [betweenSizes, setBetweenSizes] = useState<string>(initialBetweenSizes);
412→
413→  // Test recommendation inputs
414→  const [testChartId, setTestChartId] = useState<string>(charts[0]?.id ?? "");
415→  const [testHeight, setTestHeight] = useState<string>("170");
416→  const [testWeight, setTestWeight] = useState<string>("65");
417→  const [testGender, setTestGender] = useState<string>("female");
418→  const [testBodyType, setTestBodyType] = useState<string>("regular");
419→  const [testResult, setTestResult] = useState<TestResult | null>(null);
420→
421→  useEffect(() => {
422→    if (!fetcher.data) return;
423→
424→    if ("ok" in fetcher.data) {
425→      shopify.toast.show(fetcher.data.message ?? "Saved");
426→
427→      if (fetcher.data.intent === "toggle" && "enabled" in fetcher.data) {
428→        setEnabled(fetcher.data.enabled as boolean);
429→      }
430→
431→      if (fetcher.data.intent === "test-recommendation" && "testResult" in fetcher.data) {
432→        setTestResult(fetcher.data.testResult as TestResult);
433→      }
434→    } else if ("error" in fetcher.data) {
435→      shopify.toast.show(fetcher.data.error ?? "An error occurred", { isError: true });
436→    }
437→  }, [fetcher.data, shopify]);
438→
439→  const submitToggle = () => {
440→    const fd = new FormData();
441→    fd.set("intent", "toggle");
442→    fetcher.submit(fd, { method: "post" });
443→  };
444→
445→  const submitAlgorithm = (algo: string) => {
446→    setAlgorithm(algo);
447→    const fd = new FormData();
448→    fd.set("intent", "update-settings");
449→    fd.set("algorithm", algo);
450→    fetcher.submit(fd, { method: "post" });
451→  };
452→
453→  const toggleBodyType = (id: string, checked: boolean) => {
454→    const updated = bodyTypes.map((bt) => bt.id === id ? { ...bt, enabled: checked } : bt);
455→    setBodyTypes(updated);
456→    const fd = new FormData();
457→    fd.set("intent", "save-body-types");
458→    fd.set("bodyTypes", JSON.stringify(updated.map((bt) => ({ id: bt.id, enabled: bt.enabled }))));
459→    fetcher.submit(fd, { method: "post" });
460→  };
461→
462→  const submitSizingRules = () => {
463→    const fd = new FormData();
464→    fd.set("intent", "save-sizing-rules");
465→    fd.set("fitPreference", fitPreference);
466→    fd.set("betweenSizes", betweenSizes);
467→    fetcher.submit(fd, { method: "post" });
468→  };
