471→    const fd = new FormData();
472→    fd.set("intent", "test-recommendation");
473→    fd.set("chartId", testChartId);
474→    fd.set("height", testHeight);
475→    fd.set("weight", testWeight);
476→    fd.set("gender", testGender);
477→    fd.set("bodyType", testBodyType);
478→    fd.set("fitPreference", fitPreference);
479→    fetcher.submit(fd, { method: "post" });
