481→
482→  const FIT_OPTIONS = [
483→    { id: "tight", label: "Tight", description: "Fitted, closer to body — recommend smaller" },
484→    { id: "true-to-size", label: "True to Size", description: "Standard fit — no adjustment" },
485→    { id: "relaxed", label: "Relaxed", description: "Slightly loose — recommend larger" },
486→    { id: "oversized", label: "Oversized", description: "Very loose, fashion-forward — recommend up" },
487→  ];
488→
489→  const betweenSizesOptions = [
490→    { label: "Recommend smaller size", value: "smaller" },
491→    { label: "Recommend larger size", value: "larger" },
492→  ];
493→
494→  const genderOptions = [
495→    { label: "Female", value: "female" },
496→    { label: "Male", value: "male" },
497→    { label: "Unisex", value: "unisex" },
498→  ];
499→
500→  const chartOptions = charts.map((c) => ({
501→    label: `${c.name} (${c.category})`,
502→    value: c.id,
503→  }));
504→
505→  const enabledBodyTypeOptions = bodyTypes
506→    .filter((bt) => bt.enabled)
507→    .map((bt) => ({ label: bt.label, value: bt.id }));
508→
509→  // -----------------------------------------------------------------------
510→  // UPGRADE PROMPT — plan doesn't include AI
