 268→function formatDate(iso: string): string {
 269→  return new Date(iso).toLocaleDateString("en-US", {
 270→    month: "short",
 271→    day: "numeric",
 272→    year: "numeric",
 273→    hour: "2-digit",
 274→    minute: "2-digit",
 275→  });
 276→}
 277→
 278→function makeDefaultData(): ChartData {
 279→  return {
 280→    headers: ["Size", "Chest", "Waist", "Hips"],
 281→    units: { default: "in", available: ["in", "cm"] },
 282→    rows: [
 283→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 284→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 285→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 286→    ],
 287→  };
 288→}
 289→
 290→function parseChartData(raw: string): ChartData {
 291→  try {
 292→    const parsed = JSON.parse(raw) as ChartData;
 293→    if (
 294→      Array.isArray(parsed.headers) &&
 295→      parsed.units &&
 296→      Array.isArray(parsed.rows)
 297→    ) {
 298→      return parsed;
 299→    }
 300→  } catch {
 301→    // fall through
 302→  }
 303→  return makeDefaultData();
 304→}
