 315→function TableEditor({ data, onChange }: TableEditorProps) {
 316→  const headerInputRefs = useRef<(HTMLInputElement | null)[]>([]);
 317→
 318→  const updateCell = (rowIndex: number, header: string, value: string) => {
 319→    const newRows = data.rows.map((row, i) => {
 320→      if (i !== rowIndex) return row;
 321→      return { ...row, [header]: value };
 322→    });
 323→    onChange({ ...data, rows: newRows });
 324→  };
 325→
 326→  const updateHeader = (headerIndex: number, value: string) => {
 327→    const oldHeader = data.headers[headerIndex];
 328→    const newHeaders = data.headers.map((h, i) =>
 329→      i === headerIndex ? value : h,
 330→    );
 331→    const newRows = data.rows.map((row) => {
 332→      const newRow: Record<string, string> = {};
 333→      data.headers.forEach((h, i) => {
 334→        const key = i === headerIndex ? value : h;
 335→        newRow[key] = row[h] ?? "";
 336→      });
 337→      return newRow;
 338→    });
 339→    onChange({ ...data, headers: newHeaders, rows: newRows });
 340→    void oldHeader;
 341→  };
 342→
 343→  const addRow = () => {
 344→    const emptyRow: Record<string, string> = {};
 345→    data.headers.forEach((h) => {
 346→      emptyRow[h] = "";
 347→    });
 348→    onChange({ ...data, rows: [...data.rows, emptyRow] });
 349→  };
 350→
 351→  const removeRow = (rowIndex: number) => {
 352→    onChange({ ...data, rows: data.rows.filter((_, i) => i !== rowIndex) });
 353→  };
 354→
 355→  const addColumn = () => {
 356→    const newHeader = `Column ${data.headers.length + 1}`;
