 358→    const newRows = data.rows.map((row) => ({ ...row, [newHeader]: "" }));
 359→    onChange({ ...data, headers: newHeaders, rows: newRows });
 360→  };
 361→
 362→  const removeColumn = (headerIndex: number) => {
 363→    if (data.headers.length <= 1) return;
 364→    const removedHeader = data.headers[headerIndex];
 365→    const newHeaders = data.headers.filter((_, i) => i !== headerIndex);
 366→    const newRows = data.rows.map((row) => {
 367→      const newRow: Record<string, string> = {};
 368→      newHeaders.forEach((h) => {
 369→        newRow[h] = row[h] ?? "";
 370→      });
 371→      return newRow;
 372→    });
 373→    onChange({ ...data, headers: newHeaders, rows: newRows });
 374→    void removedHeader;
 375→  };
 376→
 377→  const toggleUnit = (unit: string) => {
 378→    onChange({ ...data, units: { ...data.units, default: unit } });
 379→  };
