 393→          background: transparent;
 394→          padding: 9px 10px;
 395→          font-size: 13px;
 396→          color: #202223;
 397→          outline: none;
 398→          box-sizing: border-box;
 399→          font-family: inherit;
 400→        }
 401→        .chart-header-input {
 402→          flex: 1;
 403→          border: none;
 404→          background: transparent;
 405→          font-weight: 700;
 406→          font-size: 12px;
 407→          color: #202223;
 408→          padding: 8px 4px;
 409→          outline: none;
 410→          min-width: 60px;
 411→          text-transform: uppercase;
 412→          letter-spacing: 0.04em;
 413→          font-family: inherit;
 414→        }
 415→      `}</style>
 416→
 417→      {/* Toolbar -- unit toggle + row/col count */}
 418→      <InlineStack gap="300" align="start" blockAlign="center">
 419→        <Text as="span" variant="bodySm" tone="subdued" fontWeight="semibold">
 420→          Units
 421→        </Text>
