 760→type LoaderData = Awaited<ReturnType<typeof loader>>;
 761→type ActiveTab = "chart" | "assignments" | "position" | "recommendation" | "settings";
 762→
 763→export default function SizeChartEditor() {
 764→  const loaderData = useLoaderData<typeof loader>() as LoaderData;
 765→  const { chart, assignments: initialAssignments, isNew } = loaderData;
 766→  const navigate = useNavigate();
 767→
 768→  const saveFetcher = useFetcher<typeof action>();
 769→  const statusFetcher = useFetcher<typeof action>();
 770→  const assignmentFetcher = useFetcher<typeof action>();
 771→  const duplicateFetcher = useFetcher<typeof action>();
 772→  const shopify = useAppBridge();
 773→
 774→  const [activeTab, setActiveTab] = useState<ActiveTab>("chart");
