 780→  );
 781→  const [assignments, setAssignments] =
 782→    useState<Assignment[]>(initialAssignments);
 783→  const [newAssignmentType, setNewAssignmentType] = useState("product");
 784→  const [newAssignmentValue, setNewAssignmentValue] = useState("");
 785→
 786→  // Position settings (stored in chartData.displaySettings)
 787→  const _parsedSettings = chart ? parseChartData(chart.data).displaySettings : undefined;
 788→  const [priority, setPriority] = useState(_parsedSettings?.priority ?? 1);
 789→  const [countries, setCountries] = useState<"all" | "selected">(_parsedSettings?.countries ?? "all");
 790→  const [selectedCountries, setSelectedCountries] = useState(_parsedSettings?.selectedCountries ?? "");
 791→  const [buttonPosition, setButtonPosition] = useState<"floating" | "above_desc" | "below_desc">(_parsedSettings?.buttonPosition ?? "floating");
 792→  const [recommendationEnabled, setRecommendationEnabled] = useState(
 793→    chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
 794→  );
 795→
 796→  // Track initial values for unsaved changes detection
 797→  const initialValues = useRef({
 798→    name: chart?.name ?? "Untitled Size Chart",
 799→    category: chart?.category ?? "general",
 800→    status: chart?.status ?? "draft",
 801→    chartData: chart ? parseChartData(chart.data) : makeDefaultData(),
 802→    priority: _parsedSettings?.priority ?? 1,
 803→    countries: _parsedSettings?.countries ?? "all",
 804→    selectedCountries: _parsedSettings?.selectedCountries ?? "",
 805→    buttonPosition: _parsedSettings?.buttonPosition ?? "floating",
 806→    recommendationEnabled: chart ? (parseChartData(chart.data).recommendationEnabled ?? false) : false,
 807→  });
 808→
 809→  const hasUnsavedChanges = useMemo(() => {
 810→    const init = initialValues.current;
 811→    if (name !== init.name) return true;
 812→    if (category !== init.category) return true;
 813→    if (status !== init.status) return true;
 814→    if (priority !== init.priority) return true;
 815→    if (countries !== init.countries) return true;
 816→    if (selectedCountries !== init.selectedCountries) return true;
 817→    if (buttonPosition !== init.buttonPosition) return true;
 818→    if (recommendationEnabled !== init.recommendationEnabled) return true;
 819→    if (JSON.stringify(chartData) !== JSON.stringify(init.chartData)) return true;
 820→    return false;
 821→  }, [name, category, status, chartData, priority, countries, selectedCountries, buttonPosition, recommendationEnabled]);
 822→
 823→  const isSaving = saveFetcher.state !== "idle";
 824→  const isTogglingStatus = statusFetcher.state !== "idle";
 825→  const isDuplicating = duplicateFetcher.state !== "idle";
 826→
 827→  // Check for ?saved=1 on mount (after redirect from new chart creation)
 828→  useEffect(() => {
 829→    if (typeof window !== "undefined") {
 830→      const url = new URL(window.location.href);
 831→      if (url.searchParams.get("saved") === "1") {
 832→        shopify.toast.show("Chart created successfully");
 833→        url.searchParams.delete("saved");
 834→        window.history.replaceState({}, "", url.toString());
 835→      }
 836→    }
 837→  }, [shopify]);
 838→
 839→  // Save feedback — also reset initial values on success
 840→  useEffect(() => {
 841→    if (!saveFetcher.data) return;
 842→    const data = saveFetcher.data;
 843→    if ("ok" in data && data.ok) {
 844→      shopify.toast.show(data.message ?? "Saved");
 845→      initialValues.current = {
 846→        name,
 847→        category,
 848→        status,
 849→        chartData,
 850→        priority,
 851→        countries,
 852→        selectedCountries,
 853→        buttonPosition,
 854→        recommendationEnabled,
 855→      };
 856→    } else if ("error" in data) {
 857→      shopify.toast.show(data.error ?? "An error occurred", { isError: true });
 858→    }
 859→  }, [saveFetcher.data, shopify, name, category, status, chartData, priority, countries, selectedCountries, buttonPosition, recommendationEnabled]);
 860→
 861→  // Status toggle feedback
 862→  useEffect(() => {
 863→    if (!statusFetcher.data) return;
