import { PrismaClient } from "@prisma/client";

declare global {
  // eslint-disable-next-line no-var
  var prismaGlobal: PrismaClient;
}

if (process.env.NODE_ENV !== "production") {
  if (!global.prismaGlobal) {
    global.prismaGlobal = new PrismaClient();
  }
}

const prisma = global.prismaGlobal ?? new PrismaClient();

export default prisma;

export interface Plan {
  id: string;
  name: string;
  price: number;
  interval: string;
  annualPrice: number;
  features: string[];
  limits: {
    maxCharts: number;
    csvImport: boolean;
    autoAssign: boolean;
    translateAdapt: boolean;
    analytics: boolean;
    aiRecommender: boolean;
    advancedAi: boolean;
    returnAttribution: boolean;
    prioritySupport: boolean;
    multiStore: boolean;
    dedicatedSizingPage: boolean;
    imageInCharts: boolean;
  };
}

export const PLANS: Plan[] = [
  {
    id: "free",
    name: "Free",
    price: 0,
    interval: "month",
    annualPrice: 0,
    features: [
      "3 published size charts",
      "All templates",
      "Full style customization",
      "Unit conversion (in/cm)",
      "Mobile responsive",
      "No watermark",
    ],
    limits: {
      maxCharts: 3,
