export function getPlan(planId: string): Plan {
  return PLANS.find((p) => p.id === planId) ?? PLANS[0];
}

export function hasFeature(planId: string, feature: keyof Plan["limits"]): boolean {
  const plan = getPlan(planId);
  return !!plan.limits[feature];
}

export function canCreateChart(planId: string, currentCount: number): boolean {
  const plan = getPlan(planId);
  if (plan.limits.maxCharts === -1) return true;
  return currentCount < plan.limits.maxCharts;
}

